		{
			return GetInstance(Asn1Sequence.GetInstance(obj, explicitly));
		}

		public static EnvelopedData GetInstance(object obj)
		{
			if (obj is EnvelopedData)
			{
				return (EnvelopedData)obj;
			}
			if (obj == null)
			{
