	public class LdsSecurityObject : Asn1Encodable
	{
		public const int UBDataGroups = 16;

		private DerInteger version = new DerInteger(0);

		private AlgorithmIdentifier digestAlgorithmIdentifier;

		private DataGroupHash[] datagroupHash;

		private LdsVersionInfo versionInfo;

		public BigInteger Version => version.Value;

		public AlgorithmIdentifier DigestAlgorithmIdentifier => digestAlgorithmIdentifier;

		public LdsVersionInfo VersionInfo => versionInfo;

		public static LdsSecurityObject GetInstance(object obj)
		{
			if (obj is LdsSecurityObject)
			{
				return (LdsSecurityObject)obj;
			}
			if (obj != null)
			{
				return new LdsSecurityObject(Asn1Sequence.GetInstance(obj));
			}
			return null;
		}

		private LdsSecurityObject(Asn1Sequence seq)
		{
			if (seq == null || seq.Count == 0)
			{
				throw new ArgumentException("null or empty sequence passed.");
			}
			IEnumerator enumerator = seq.GetEnumerator();
			enumerator.MoveNext();
			version = DerInteger.GetInstance(enumerator.Current);
			enumerator.MoveNext();
			digestAlgorithmIdentifier = AlgorithmIdentifier.GetInstance(enumerator.Current);
			enumerator.MoveNext();
			Asn1Sequence instance = Asn1Sequence.GetInstance(enumerator.Current);
			if (version.Value.Equals(BigInteger.One))
			{
				enumerator.MoveNext();
				versionInfo = LdsVersionInfo.GetInstance(enumerator.Current);
			}
			CheckDatagroupHashSeqSize(instance.Count);
			datagroupHash = new DataGroupHash[instance.Count];
			for (int i = 0; i < instance.Count; i++)
			{
				datagroupHash[i] = DataGroupHash.GetInstance(instance[i]);
			}
		}

		public LdsSecurityObject(AlgorithmIdentifier digestAlgorithmIdentifier, DataGroupHash[] datagroupHash)
		{
			version = new DerInteger(0);
			this.digestAlgorithmIdentifier = digestAlgorithmIdentifier;
			this.datagroupHash = datagroupHash;
			CheckDatagroupHashSeqSize(datagroupHash.Length);
		}

		public LdsSecurityObject(AlgorithmIdentifier digestAlgorithmIdentifier, DataGroupHash[] datagroupHash, LdsVersionInfo versionInfo)
		{
			version = new DerInteger(1);
			this.digestAlgorithmIdentifier = digestAlgorithmIdentifier;
			this.datagroupHash = datagroupHash;
			this.versionInfo = versionInfo;
			CheckDatagroupHashSeqSize(datagroupHash.Length);
		}

		private void CheckDatagroupHashSeqSize(int size)
		{
			if (size < 2 || size > 16)
			{
				throw new ArgumentException("wrong size in DataGroupHashValues : not in (2.." + 16 + ")");
			}
		}

		public DataGroupHash[] GetDatagroupHash()
		{
			return datagroupHash;
		}

		public override Asn1Object ToAsn1Object()
		{
			DerSequence derSequence = new DerSequence(datagroupHash);
			Asn1EncodableVector asn1EncodableVector = new Asn1EncodableVector(version, digestAlgorithmIdentifier, derSequence);
			asn1EncodableVector.AddOptional(versionInfo);
			return new DerSequence(asn1EncodableVector);
		}
	}
	public class LdsVersionInfo : Asn1Encodable
	{
		private DerPrintableString ldsVersion;

		private DerPrintableString unicodeVersion;

		public LdsVersionInfo(string ldsVersion, string unicodeVersion)
		{
			this.ldsVersion = new DerPrintableString(ldsVersion);
			this.unicodeVersion = new DerPrintableString(unicodeVersion);
		}

		private LdsVersionInfo(Asn1Sequence seq)
		{
			if (seq.Count != 2)
			{
				throw new ArgumentException("sequence wrong size for LDSVersionInfo", "seq");
			}
			ldsVersion = DerPrintableString.GetInstance(seq[0]);
			unicodeVersion = DerPrintableString.GetInstance(seq[1]);
		}

		public static LdsVersionInfo GetInstance(object obj)
		{
			if (obj is LdsVersionInfo)
			{
				return (LdsVersionInfo)obj;
			}
			if (obj != null)
			{
				return new LdsVersionInfo(Asn1Sequence.GetInstance(obj));
			}
			return null;
		}

		public virtual string GetLdsVersion()
		{
			return ldsVersion.GetString();
		}

		public virtual string GetUnicodeVersion()
		{
			return unicodeVersion.GetString();
		}

		public override Asn1Object ToAsn1Object()
		{
			return new DerSequence(ldsVersion, unicodeVersion);
		}
	}
}
namespace Org.BouncyCastle.Asn1.IsisMtt.Ocsp
{
	public class CertHash : Asn1Encodable
	{
		private readonly AlgorithmIdentifier hashAlgorithm;

		private readonly byte[] certificateHash;

		public AlgorithmIdentifier HashAlgorithm => hashAlgorithm;

		public byte[] CertificateHash => (byte[])certificateHash.Clone();

		public static CertHash GetInstance(object obj)
		{
			if (obj == null || obj is CertHash)
			{
				return (CertHash)obj;
			}
			if (obj is Asn1Sequence)
			{
				return new CertHash((Asn1Sequence)obj);
			}
			throw new ArgumentException("unknown object in factory: " + Platform.GetTypeName(obj), "obj");
		}

		private CertHash(Asn1Sequence seq)
		{
			if (seq.Count != 2)
			{
				throw new ArgumentException("Bad sequence size: " + seq.Count);
			}
			hashAlgorithm = AlgorithmIdentifier.GetInstance(seq[0]);
			certificateHash = Asn1OctetString.GetInstance(seq[1]).GetOctets();
		}

		public CertHash(AlgorithmIdentifier hashAlgorithm, byte[] certificateHash)
		{
			if (hashAlgorithm == null)
			{
				throw new ArgumentNullException("hashAlgorithm");
			}
			if (certificateHash == null)
			{
				throw new ArgumentNullException("certificateHash");
			}
			this.hashAlgorithm = hashAlgorithm;
			this.certificateHash = (byte[])certificateHash.Clone();
		}

		public override Asn1Object ToAsn1Object()
		{
			return new DerSequence(hashAlgorithm, new DerOctetString(certificateHash));
		}
	}
	public class RequestedCertificate : Asn1Encodable, IAsn1Choice
	{
		public enum Choice
		{
			Certificate = -1,
			PublicKeyCertificate,
			AttributeCertificate
		}

		private readonly X509CertificateStructure cert;

		private readonly byte[] publicKeyCert;

		private readonly byte[] attributeCert;

		public Choice Type
		{
			get
			{
				if (cert != null)
				{
					return Choice.Certificate;
				}
				if (publicKeyCert != null)
				{
					return Choice.PublicKeyCertificate;
				}
				return Choice.AttributeCertificate;
			}
		}

		public static RequestedCertificate GetInstance(object obj)
		{
			if (obj == null || obj is RequestedCertificate)
			{
				return (RequestedCertificate)obj;
			}
			if (obj is Asn1Sequence)
			{
				return new RequestedCertificate(X509CertificateStructure.GetInstance(obj));
			}
			if (obj is Asn1TaggedObject)
			{
				return new RequestedCertificate((Asn1TaggedObject)obj);
			}
			throw new ArgumentException("unknown object in factory: " + Platform.GetTypeName(obj), "obj");
		}

		public static RequestedCertificate GetInstance(Asn1TaggedObject obj, bool isExplicit)
		{
			if (!isExplicit)
			{
				throw new ArgumentException("choice item must be explicitly tagged");
			}
			return GetInstance(obj.GetObject());
		}

		private RequestedCertificate(Asn1TaggedObject tagged)
		{
			switch ((Choice)tagged.TagNo)
			{
			case Choice.AttributeCertificate:
				attributeCert = Asn1OctetString.GetInstance(tagged, isExplicit: true).GetOctets();
				break;
			case Choice.PublicKeyCertificate:
				publicKeyCert = Asn1OctetString.GetInstance(tagged, isExplicit: true).GetOctets();
				break;
			default:
				throw new ArgumentException("unknown tag number: " + tagged.TagNo);
			}
		}

		public RequestedCertificate(X509CertificateStructure certificate)
		{
			cert = certificate;
		}

		public RequestedCertificate(Choice type, byte[] certificateOctets)
			: this(new DerTaggedObject((int)type, new DerOctetString(certificateOctets)))
		{
		}

		public byte[] GetCertificateBytes()
		{
			if (cert != null)
			{
				try
				{
					return cert.GetEncoded();
				}
				catch (IOException ex)
				{
					throw new InvalidOperationException("can't decode certificate: " + ex);
				}
			}
			if (publicKeyCert != null)
			{
				return publicKeyCert;
			}
			return attributeCert;
		}

		public override Asn1Object ToAsn1Object()
		{
			if (publicKeyCert != null)
			{
				return new DerTaggedObject(0, new DerOctetString(publicKeyCert));
			}
			if (attributeCert != null)
			{
				return new DerTaggedObject(1, new DerOctetString(attributeCert));
			}
			return cert.ToAsn1Object();
		}
	}
}
