			return new PbeS2Parameters(Asn1Sequence.GetInstance(obj));
		}

		public PbeS2Parameters(KeyDerivationFunc keyDevFunc, EncryptionScheme encScheme)
		{
			func = keyDevFunc;
			scheme = encScheme;
