		public RC2CbcParameter(int parameterVersion, byte[] iv)
		{
			version = new DerInteger(parameterVersion);
			this.iv = new DerOctetString(iv);
		}

		private RC2CbcParameter(Asn1Sequence seq)
		{
			if (seq.Count == 1)
			{
				iv = (Asn1OctetString)seq[0];
