	public class X9FieldID : Asn1Encodable
	{
		private readonly DerObjectIdentifier id;

		private readonly Asn1Object parameters;

		public DerObjectIdentifier Identifier => id;

		public Asn1Object Parameters => parameters;

		public X9FieldID(BigInteger primeP)
		{
			id = X9ObjectIdentifiers.PrimeField;
			parameters = new DerInteger(primeP);
		}

		public X9FieldID(int m, int k1)
			: this(m, k1, 0, 0)
		{
		}

		public X9FieldID(int m, int k1, int k2, int k3)
		{
			id = X9ObjectIdentifiers.CharacteristicTwoField;
			Asn1EncodableVector asn1EncodableVector = new Asn1EncodableVector(new DerInteger(m));
			if (k2 == 0)
			{
				if (k3 != 0)
				{
					throw new ArgumentException("inconsistent k values");
				}
				asn1EncodableVector.Add(X9ObjectIdentifiers.TPBasis, new DerInteger(k1));
			}
			else
			{
				if (k2 <= k1 || k3 <= k2)
				{
					throw new ArgumentException("inconsistent k values");
				}
				asn1EncodableVector.Add(X9ObjectIdentifiers.PPBasis, new DerSequence(new DerInteger(k1), new DerInteger(k2), new DerInteger(k3)));
			}
			parameters = new DerSequence(asn1EncodableVector);
		}

		private X9FieldID(Asn1Sequence seq)
		{
			id = DerObjectIdentifier.GetInstance(seq[0]);
			parameters = seq[1].ToAsn1Object();
		}

		public static X9FieldID GetInstance(object obj)
		{
			if (obj is X9FieldID)
			{
				return (X9FieldID)obj;
			}
			if (obj == null)
			{
				return null;
			}
			return new X9FieldID(Asn1Sequence.GetInstance(obj));
		}

		public override Asn1Object ToAsn1Object()
		{
			return new DerSequence(id, parameters);
		}
	}
	public abstract class X9IntegerConverter
	{
		public static int GetByteLength(ECFieldElement fe)
		{
			return (fe.FieldSize + 7) / 8;
		}

		public static int GetByteLength(Org.BouncyCastle.Math.EC.ECCurve c)
		{
			return (c.FieldSize + 7) / 8;
		}

		public static byte[] IntegerToBytes(BigInteger s, int qLength)
		{
			byte[] array = s.ToByteArrayUnsigned();
			if (qLength < array.Length)
			{
				byte[] array2 = new byte[qLength];
				Array.Copy(array, array.Length - array2.Length, array2, 0, array2.Length);
				return array2;
			}
			if (qLength > array.Length)
			{
				byte[] array3 = new byte[qLength];
				Array.Copy(array, 0, array3, array3.Length - array.Length, array.Length);
				return array3;
			}
			return array;
		}
	}
	public abstract class X9ObjectIdentifiers
	{
		internal const string AnsiX962 = "1.2.840.10045";

		[Obsolete("Use 'id_ecSigType' instead")]
		public const string IdECSigType = "1.2.840.10045.4";

		[Obsolete("Use 'id_publicKeyType' instead")]
		public const string IdPublicKeyType = "1.2.840.10045.2";

		public static readonly DerObjectIdentifier ansi_X9_62 = new DerObjectIdentifier("1.2.840.10045");

		public static readonly DerObjectIdentifier IdFieldType = ansi_X9_62.Branch("1");

		public static readonly DerObjectIdentifier PrimeField = IdFieldType.Branch("1");

		public static readonly DerObjectIdentifier CharacteristicTwoField = IdFieldType.Branch("2");

		public static readonly DerObjectIdentifier GNBasis = CharacteristicTwoField.Branch("3.1");

		public static readonly DerObjectIdentifier TPBasis = CharacteristicTwoField.Branch("3.2");

		public static readonly DerObjectIdentifier PPBasis = CharacteristicTwoField.Branch("3.3");

