	public class BerOctetString : DerOctetString, IEnumerable
	{
		private static readonly int DefaultChunkSize = 1000;

		private readonly int chunkSize;

		private readonly Asn1OctetString[] octs;

		public static BerOctetString FromSequence(Asn1Sequence seq)
		{
			int count = seq.Count;
			Asn1OctetString[] array = new Asn1OctetString[count];
			for (int i = 0; i < count; i++)
			{
				array[i] = Asn1OctetString.GetInstance(seq[i]);
			}
			return new BerOctetString(array);
		}

		private static byte[] ToBytes(Asn1OctetString[] octs)
		{
			MemoryStream memoryStream = new MemoryStream();
			foreach (Asn1OctetString asn1OctetString in octs)
			{
				byte[] octets = asn1OctetString.GetOctets();
				memoryStream.Write(octets, 0, octets.Length);
			}
			return memoryStream.ToArray();
		}

		private static Asn1OctetString[] ToOctetStringArray(IEnumerable e)
		{
			IList list = Platform.CreateArrayList(e);
			int count = list.Count;
			Asn1OctetString[] array = new Asn1OctetString[count];
			for (int i = 0; i < count; i++)
			{
				array[i] = Asn1OctetString.GetInstance(list[i]);
			}
			return array;
		}

		[Obsolete("Will be removed")]
		public BerOctetString(IEnumerable e)
			: this(ToOctetStringArray(e))
		{
		}

		public BerOctetString(byte[] str)
			: this(str, DefaultChunkSize)
		{
		}

		public BerOctetString(Asn1OctetString[] octs)
			: this(octs, DefaultChunkSize)
		{
		}

		public BerOctetString(byte[] str, int chunkSize)
			: this(str, null, chunkSize)
		{
		}

		public BerOctetString(Asn1OctetString[] octs, int chunkSize)
			: this(ToBytes(octs), octs, chunkSize)
		{
		}

		private BerOctetString(byte[] str, Asn1OctetString[] octs, int chunkSize)
			: base(str)
		{
			this.octs = octs;
			this.chunkSize = chunkSize;
		}

		public IEnumerator GetEnumerator()
		{
			if (octs == null)
			{
				return GenerateOcts().GetEnumerator();
			}
			return octs.GetEnumerator();
		}

		[Obsolete("Use GetEnumerator() instead")]
		public IEnumerator GetObjects()
		{
			return GetEnumerator();
		}

		private IList GenerateOcts()
		{
			IList list = Platform.CreateArrayList();
			for (int i = 0; i < str.Length; i += chunkSize)
			{
				int num = System.Math.Min(str.Length, i + chunkSize);
				byte[] array = new byte[num - i];
				Array.Copy(str, i, array, 0, array.Length);
				list.Add(new DerOctetString(array));
			}
			return list;
		}

		internal override void Encode(DerOutputStream derOut)
		{
			if (derOut is Asn1OutputStream || derOut is BerOutputStream)
			{
				derOut.WriteByte(36);
				derOut.WriteByte(128);
				{
					IEnumerator enumerator = GetEnumerator();
					try
					{
						while (enumerator.MoveNext())
						{
							Asn1OctetString obj = (Asn1OctetString)enumerator.Current;
							derOut.WriteObject(obj);
						}
					}
					finally
					{
						IDisposable disposable = enumerator as IDisposable;
						if (disposable != null)
						{
							disposable.Dispose();
						}
					}
				}
				derOut.WriteByte(0);
				derOut.WriteByte(0);
			}
			else
			{
				base.Encode(derOut);
			}
		}
	}
	public class BerOctetStringGenerator : BerGenerator
	{
		private class BufferedBerOctetStream : BaseOutputStream
		{
			private byte[] _buf;

			private int _off;

			private readonly BerOctetStringGenerator _gen;

			private readonly DerOutputStream _derOut;

			internal BufferedBerOctetStream(BerOctetStringGenerator gen, byte[] buf)
			{
				_gen = gen;
				_buf = buf;
				_off = 0;
				_derOut = new DerOutputStream(_gen.Out);
			}

			public override void WriteByte(byte b)
			{
				_buf[_off++] = b;
				if (_off == _buf.Length)
				{
					DerOctetString.Encode(_derOut, _buf, 0, _off);
					_off = 0;
				}
			}

			public override void Write(byte[] buf, int offset, int len)
			{
				while (len > 0)
				{
					int num = System.Math.Min(len, _buf.Length - _off);
					if (num == _buf.Length)
					{
						DerOctetString.Encode(_derOut, buf, offset, num);
					}
					else
					{
						Array.Copy(buf, offset, _buf, _off, num);
						_off += num;
						if (_off < _buf.Length)
						{
							break;
						}
						DerOctetString.Encode(_derOut, _buf, 0, _off);
						_off = 0;
					}
					offset += num;
					len -= num;
				}
			}

			public override void Close()
			{
				if (_off != 0)
				{
					DerOctetString.Encode(_derOut, _buf, 0, _off);
				}
				_gen.WriteBerEnd();
				base.Close();
			}
		}

		public BerOctetStringGenerator(Stream outStream)
			: base(outStream)
		{
			WriteBerHeader(36);
		}

		public BerOctetStringGenerator(Stream outStream, int tagNo, bool isExplicit)
			: base(outStream, tagNo, isExplicit)
		{
			WriteBerHeader(36);
		}

		public Stream GetOctetOutputStream()
		{
			return GetOctetOutputStream(new byte[1000]);
		}

		public Stream GetOctetOutputStream(int bufSize)
		{
			if (bufSize >= 1)
			{
				return GetOctetOutputStream(new byte[bufSize]);
			}
			return GetOctetOutputStream();
		}

		public Stream GetOctetOutputStream(byte[] buf)
		{
			return new BufferedBerOctetStream(this, buf);
		}
	}
