	internal class ConstructedOctetStream : BaseInputStream
	{
		private readonly Asn1StreamParser _parser;

		private bool _first = true;

		private Stream _currentStream;

		internal ConstructedOctetStream(Asn1StreamParser parser)
		{
			_parser = parser;
		}

		public override int Read(byte[] buffer, int offset, int count)
		{
			if (_currentStream == null)
			{
				if (!_first)
				{
					return 0;
				}
				Asn1OctetStringParser nextParser = GetNextParser();
				if (nextParser == null)
				{
					return 0;
				}
				_first = false;
				_currentStream = nextParser.GetOctetStream();
			}
			int num = 0;
			while (true)
			{
				int num2 = _currentStream.Read(buffer, offset + num, count - num);
				if (num2 > 0)
				{
					num += num2;
					if (num == count)
					{
						return num;
					}
					continue;
				}
				Asn1OctetStringParser nextParser2 = GetNextParser();
				if (nextParser2 == null)
				{
					break;
				}
				_currentStream = nextParser2.GetOctetStream();
			}
			_currentStream = null;
			return num;
		}

		public override int ReadByte()
		{
			if (_currentStream == null)
			{
				if (!_first)
				{
					return 0;
				}
				Asn1OctetStringParser nextParser = GetNextParser();
				if (nextParser == null)
				{
					return 0;
				}
				_first = false;
				_currentStream = nextParser.GetOctetStream();
			}
			while (true)
			{
				int num = _currentStream.ReadByte();
				if (num >= 0)
				{
					return num;
				}
				Asn1OctetStringParser nextParser2 = GetNextParser();
				if (nextParser2 == null)
				{
					break;
				}
				_currentStream = nextParser2.GetOctetStream();
			}
			_currentStream = null;
			return -1;
		}

		private Asn1OctetStringParser GetNextParser()
		{
			IAsn1Convertible asn1Convertible = _parser.ReadObject();
			if (asn1Convertible == null)
			{
				return null;
			}
			if (asn1Convertible is Asn1OctetStringParser)
			{
				return (Asn1OctetStringParser)asn1Convertible;
			}
			throw new IOException("unknown object encountered: " + Platform.GetTypeName(asn1Convertible));
		}
	}
	internal abstract class LimitedInputStream : BaseInputStream
	{
		protected readonly Stream _in;

		private int _limit;

		internal virtual int Limit => _limit;

		internal LimitedInputStream(Stream inStream, int limit)
		{
			_in = inStream;
			_limit = limit;
		}

		protected virtual void SetParentEofDetect(bool on)
		{
			if (_in is IndefiniteLengthInputStream)
			{
				((IndefiniteLengthInputStream)_in).SetEofOn00(on);
			}
		}
	}
	internal class DefiniteLengthInputStream : LimitedInputStream
	{
		private static readonly byte[] EmptyBytes = new byte[0];

		private readonly int _originalLength;

		private int _remaining;

		internal int Remaining => _remaining;

		internal DefiniteLengthInputStream(Stream inStream, int length, int limit)
			: base(inStream, limit)
		{
			if (length < 0)
			{
				throw new ArgumentException("negative lengths not allowed", "length");
			}
			_originalLength = length;
			_remaining = length;
			if (length == 0)
			{
				SetParentEofDetect(on: true);
			}
		}

		public override int ReadByte()
		{
			if (_remaining == 0)
			{
				return -1;
			}
			int num = _in.ReadByte();
			if (num < 0)
			{
				throw new EndOfStreamException("DEF length " + _originalLength + " object truncated by " + _remaining);
			}
			if (--_remaining == 0)
			{
				SetParentEofDetect(on: true);
			}
			return num;
		}

		public override int Read(byte[] buf, int off, int len)
		{
			if (_remaining == 0)
			{
				return 0;
			}
			int count = System.Math.Min(len, _remaining);
			int num = _in.Read(buf, off, count);
			if (num < 1)
			{
				throw new EndOfStreamException("DEF length " + _originalLength + " object truncated by " + _remaining);
			}
			if ((_remaining -= num) == 0)
			{
				SetParentEofDetect(on: true);
			}
			return num;
		}

		internal void ReadAllIntoByteArray(byte[] buf)
		{
			if (_remaining != buf.Length)
			{
				throw new ArgumentException("buffer length not right for data");
			}
			if (_remaining != 0)
			{
				int limit = Limit;
				if (_remaining >= limit)
				{
					throw new IOException("corrupted stream - out of bounds length found: " + _remaining + " >= " + limit);
				}
				if ((_remaining -= Streams.ReadFully(_in, buf)) != 0)
				{
					throw new EndOfStreamException("DEF length " + _originalLength + " object truncated by " + _remaining);
				}
				SetParentEofDetect(on: true);
			}
		}

		internal byte[] ToArray()
		{
			if (_remaining == 0)
			{
				return EmptyBytes;
			}
			int limit = Limit;
			if (_remaining >= limit)
			{
				throw new IOException("corrupted stream - out of bounds length found: " + _remaining + " >= " + limit);
			}
			byte[] array = new byte[_remaining];
			if ((_remaining -= Streams.ReadFully(_in, array)) != 0)
			{
				throw new EndOfStreamException("DEF length " + _originalLength + " object truncated by " + _remaining);
			}
			SetParentEofDetect(on: true);
			return array;
		}
	}
