namespace Org.BouncyCastle.Bcpg
{
	public class UserAttributeSubpacket
	{
		internal readonly UserAttributeSubpacketTag type;

		private readonly bool longLength;

		protected readonly byte[] data;

		public virtual UserAttributeSubpacketTag SubpacketType => type;

		protected internal UserAttributeSubpacket(UserAttributeSubpacketTag type, byte[] data)
			: this(type, forceLongLength: false, data)
		{
		}

		protected internal UserAttributeSubpacket(UserAttributeSubpacketTag type, bool forceLongLength, byte[] data)
		{
			this.type = type;
			longLength = forceLongLength;
			this.data = data;
		}

		public virtual byte[] GetData()
		{
			return data;
		}

		public virtual void Encode(Stream os)
		{
			int num = data.Length + 1;
			if (num < 192 && !longLength)
			{
				os.WriteByte((byte)num);
			}
			else if (num <= 8383 && !longLength)
			{
				num -= 192;
				os.WriteByte((byte)(((num >> 8) & 0xFF) + 192));
				os.WriteByte((byte)num);
			}
			else
			{
				os.WriteByte(byte.MaxValue);
				os.WriteByte((byte)(num >> 24));
				os.WriteByte((byte)(num >> 16));
				os.WriteByte((byte)(num >> 8));
				os.WriteByte((byte)num);
			}
			os.WriteByte((byte)type);
			os.Write(data, 0, data.Length);
		}

		public override bool Equals(object obj)
		{
			if (obj == this)
			{
				return true;
			}
			if (!(obj is UserAttributeSubpacket userAttributeSubpacket))
			{
				return false;
			}
			if (type == userAttributeSubpacket.type)
			{
				return Arrays.AreEqual(data, userAttributeSubpacket.data);
			}
			return false;
		}

		public override int GetHashCode()
		{
			return type.GetHashCode() ^ Arrays.GetHashCode(data);
		}
	}
}
namespace Org.BouncyCastle.Bcpg.Attr
{
	public class ImageAttrib : UserAttributeSubpacket
	{
		public enum Format : byte
		{
			Jpeg = 1
		}

		private static readonly byte[] Zeroes = new byte[12];

		private int hdrLength;

		private int _version;

		private int _encoding;

		private byte[] imageData;

		public virtual int Version => _version;

		public virtual int Encoding => _encoding;

		public ImageAttrib(byte[] data)
			: this(forceLongLength: false, data)
		{
		}

		public ImageAttrib(bool forceLongLength, byte[] data)
			: base(UserAttributeSubpacketTag.ImageAttribute, forceLongLength, data)
		{
			hdrLength = ((data[1] & 0xFF) << 8) | (data[0] & 0xFF);
			_version = data[2] & 0xFF;
			_encoding = data[3] & 0xFF;
			imageData = new byte[data.Length - hdrLength];
			Array.Copy(data, hdrLength, imageData, 0, imageData.Length);
		}

		public ImageAttrib(Format imageType, byte[] imageData)
			: this(ToByteArray(imageType, imageData))
		{
		}

		private static byte[] ToByteArray(Format imageType, byte[] imageData)
		{
			MemoryStream memoryStream = new MemoryStream();
			memoryStream.WriteByte(16);
			memoryStream.WriteByte(0);
			memoryStream.WriteByte(1);
			memoryStream.WriteByte((byte)imageType);
			memoryStream.Write(Zeroes, 0, Zeroes.Length);
			memoryStream.Write(imageData, 0, imageData.Length);
			return memoryStream.ToArray();
		}

		public virtual byte[] GetImageData()
		{
			return imageData;
		}
	}
}
