				pubKeyPacket = new PublicKeyPacket(bcpgIn);
			}
			s2kUsage = bcpgIn.ReadByte();
			if (s2kUsage == 255 || s2kUsage == 254)
			{
				encAlgorithm = (SymmetricKeyAlgorithmTag)bcpgIn.ReadByte();
				s2k = new S2k(bcpgIn);
			}
			else
			{
				encAlgorithm = (SymmetricKeyAlgorithmTag)s2kUsage;
