				MemoryStream memoryStream2 = new MemoryStream();
				SignatureSubpacket[] hashedSubPackets = GetHashedSubPackets();
				for (int i = 0; i != hashedSubPackets.Length; i++)
				{
					hashedSubPackets[i].Encode(memoryStream2);
				}
				byte[] array2 = memoryStream2.ToArray();
				memoryStream.WriteByte((byte)(array2.Length >> 8));
				memoryStream.WriteByte((byte)array2.Length);
				memoryStream.Write(array2, 0, array2.Length);
				byte[] array3 = memoryStream.ToArray();
				memoryStream.WriteByte((byte)Version);
				memoryStream.WriteByte(byte.MaxValue);
				memoryStream.WriteByte((byte)(array3.Length >> 24));
				memoryStream.WriteByte((byte)(array3.Length >> 16));
				memoryStream.WriteByte((byte)(array3.Length >> 8));
				memoryStream.WriteByte((byte)array3.Length);
				array = memoryStream.ToArray();
			}
			return array;
		}

		public MPInteger[] GetSignature()
		{
			return signature;
		}

		public byte[] GetSignatureBytes()
		{
			if (signatureEncoding != null)
			{
				return (byte[])signatureEncoding.Clone();
			}
			MemoryStream memoryStream = new MemoryStream();
			BcpgOutputStream bcpgOutputStream = new BcpgOutputStream(memoryStream);
			MPInteger[] array = signature;
			foreach (MPInteger bcpgObject in array)
			{
				try
				{
					bcpgOutputStream.WriteObject(bcpgObject);
				}
				catch (IOException ex)
				{
					throw new Exception("internal error: " + ex);
				}
			}
			return memoryStream.ToArray();
		}

		public SignatureSubpacket[] GetHashedSubPackets()
		{
			return hashedData;
		}

		public SignatureSubpacket[] GetUnhashedSubPackets()
		{
			return unhashedData;
		}

		public override void Encode(BcpgOutputStream bcpgOut)
		{
			MemoryStream memoryStream = new MemoryStream();
			BcpgOutputStream bcpgOutputStream = new BcpgOutputStream(memoryStream);
			bcpgOutputStream.WriteByte((byte)version);
			if (version == 3 || version == 2)
			{
				bcpgOutputStream.Write(5, (byte)signatureType);
				bcpgOutputStream.WriteInt((int)(creationTime / 1000));
				bcpgOutputStream.WriteLong(keyId);
				bcpgOutputStream.Write((byte)keyAlgorithm, (byte)hashAlgorithm);
			}
			else
			{
				if (version != 4)
				{
					throw new IOException("unknown version: " + version);
				}
				bcpgOutputStream.Write((byte)signatureType, (byte)keyAlgorithm, (byte)hashAlgorithm);
				EncodeLengthAndData(bcpgOutputStream, GetEncodedSubpackets(hashedData));
				EncodeLengthAndData(bcpgOutputStream, GetEncodedSubpackets(unhashedData));
			}
			bcpgOutputStream.Write(fingerprint);
			if (signature != null)
			{
				bcpgOutputStream.WriteObjects(signature);
			}
			else
			{
				bcpgOutputStream.Write(signatureEncoding);
			}
			bcpgOut.WritePacket(PacketTag.Signature, memoryStream.ToArray(), oldFormat: true);
		}

		private static void EncodeLengthAndData(BcpgOutputStream pOut, byte[] data)
		{
			pOut.WriteShort((short)data.Length);
			pOut.Write(data);
		}

		private static byte[] GetEncodedSubpackets(SignatureSubpacket[] ps)
		{
			MemoryStream memoryStream = new MemoryStream();
			foreach (SignatureSubpacket signatureSubpacket in ps)
			{
				signatureSubpacket.Encode(memoryStream);
			}
			return memoryStream.ToArray();
		}

		private void setCreationTime()
		{
			SignatureSubpacket[] array = hashedData;
			foreach (SignatureSubpacket signatureSubpacket in array)
			{
				if (signatureSubpacket is SignatureCreationTime)
				{
					creationTime = DateTimeUtilities.DateTimeToUnixMs(((SignatureCreationTime)signatureSubpacket).GetTime());
					break;
				}
			}
		}
	}
	public class SignatureSubpacketsParser
	{
		private readonly Stream input;

		public SignatureSubpacketsParser(Stream input)
		{
			this.input = input;
		}

		public SignatureSubpacket ReadPacket()
		{
			int num = input.ReadByte();
			if (num < 0)
			{
				return null;
			}
			int num2 = 0;
			bool isLongLength = false;
			if (num < 192)
			{
				num2 = num;
			}
			else if (num <= 223)
			{
				num2 = (num - 192 << 8) + input.ReadByte() + 192;
			}
			else
			{
				if (num != 255)
				{
					throw new IOException("unexpected length header");
				}
				isLongLength = true;
				num2 = (input.ReadByte() << 24) | (input.ReadByte() << 16) | (input.ReadByte() << 8) | input.ReadByte();
			}
			int num3 = input.ReadByte();
			if (num3 < 0)
			{
				throw new EndOfStreamException("unexpected EOF reading signature sub packet");
			}
			if (num2 <= 0)
			{
				throw new EndOfStreamException("out of range data found in signature sub packet");
			}
			byte[] array = new byte[num2 - 1];
			int num4 = Streams.ReadFully(input, array);
			bool critical = (num3 & 0x80) != 0;
			SignatureSubpacketTag signatureSubpacketTag = (SignatureSubpacketTag)(num3 & 0x7F);
			if (num4 != array.Length)
			{
				array = signatureSubpacketTag switch
				{
					SignatureSubpacketTag.CreationTime => CheckData(array, 4, num4, "Signature Creation Time"), 
					SignatureSubpacketTag.IssuerKeyId => CheckData(array, 8, num4, "Issuer"), 
					SignatureSubpacketTag.KeyExpireTime => CheckData(array, 4, num4, "Signature Key Expiration Time"), 
					SignatureSubpacketTag.ExpireTime => CheckData(array, 4, num4, "Signature Expiration Time"), 
					_ => throw new EndOfStreamException("truncated subpacket data."), 
				};
			}
			switch (signatureSubpacketTag)
			{
			case SignatureSubpacketTag.CreationTime:
				return new SignatureCreationTime(critical, isLongLength, array);
			case SignatureSubpacketTag.KeyExpireTime:
				return new KeyExpirationTime(critical, isLongLength, array);
			case SignatureSubpacketTag.ExpireTime:
				return new SignatureExpirationTime(critical, isLongLength, array);
			case SignatureSubpacketTag.Revocable:
				return new Revocable(critical, isLongLength, array);
			case SignatureSubpacketTag.Exportable:
				return new Exportable(critical, isLongLength, array);
			case SignatureSubpacketTag.IssuerKeyId:
				return new IssuerKeyId(critical, isLongLength, array);
			case SignatureSubpacketTag.TrustSig:
				return new TrustSignature(critical, isLongLength, array);
			case SignatureSubpacketTag.PreferredSymmetricAlgorithms:
			case SignatureSubpacketTag.PreferredHashAlgorithms:
			case SignatureSubpacketTag.PreferredCompressionAlgorithms:
				return new PreferredAlgorithms(signatureSubpacketTag, critical, isLongLength, array);
			case SignatureSubpacketTag.KeyFlags:
				return new KeyFlags(critical, isLongLength, array);
			case SignatureSubpacketTag.PrimaryUserId:
				return new PrimaryUserId(critical, isLongLength, array);
			case SignatureSubpacketTag.SignerUserId:
				return new SignerUserId(critical, isLongLength, array);
			case SignatureSubpacketTag.NotationData:
				return new NotationData(critical, isLongLength, array);
			default:
				return new SignatureSubpacket(signatureSubpacketTag, critical, isLongLength, array);
			}
		}

		private byte[] CheckData(byte[] data, int expected, int bytesRead, string name)
		{
			if (bytesRead != expected)
			{
				throw new EndOfStreamException("truncated " + name + " subpacket data.");
			}
			return Arrays.CopyOfRange(data, 0, expected);
		}
	}
	public enum SignatureSubpacketTag
	{
		CreationTime = 2,
		ExpireTime = 3,
		Exportable = 4,
		TrustSig = 5,
		RegExp = 6,
		Revocable = 7,
		KeyExpireTime = 9,
		Placeholder = 10,
		PreferredSymmetricAlgorithms = 11,
		RevocationKey = 12,
		IssuerKeyId = 16,
		NotationData = 20,
		PreferredHashAlgorithms = 21,
		PreferredCompressionAlgorithms = 22,
		KeyServerPreferences = 23,
		PreferredKeyServer = 24,
		PrimaryUserId = 25,
		PolicyUrl = 26,
		KeyFlags = 27,
		SignerUserId = 28,
		RevocationReason = 29,
		Features = 30,
		SignatureTarget = 31,
		EmbeddedSignature = 32
	}
