		public void AddSigner(AsymmetricKeyParameter privateKey, Org.BouncyCastle.X509.X509Certificate cert, string encryptionOID, string digestOID, Org.BouncyCastle.Asn1.Cms.AttributeTable signedAttr, Org.BouncyCastle.Asn1.Cms.AttributeTable unsignedAttr)
		{
