		public static readonly Srp6GroupParameters rfc5054_6144 = FromNG("", "05");

		public static readonly Srp6GroupParameters rfc5054_8192 = FromNG("", "13");

		private static BigInteger FromHex(string hex)
		{
			return new BigInteger(1, Hex.DecodeStrict(hex));
		}

		private static Srp6GroupParameters FromNG(string hexN, string hexG)
		{
			return new Srp6GroupParameters(FromHex(hexN), FromHex(hexG));
		}
