			P(tempState1);
			for (int i = 0; i < columns; i++)
			{
				ulong[] array;
				ulong[] array2 = (array = state);
				int num4 = i;
				nint num5 = num4;
				array2[num4] = array[num5] ^ tempState1[i];
			}
			int num6 = hashSize / 8;
			for (int j = columns - num6; j < columns; j++)
			{
				Pack.UInt64_To_LE(state[j], output, outOff);
				outOff += 8;
			}
