		private static ulong MixColumn(ulong c)
		{
			ulong num = ((c & 0x7F7F7F7F7F7F7F7FL) << 1) ^ (((c & 0x8080808080808080uL) >> 7) * 29);
			ulong num2 = Rotate(8, c) ^ c;
			num2 ^= Rotate(16, num2);
