				uint num21 = Pack.LE_To_UInt32(key, 0);
				array[0][0] = num21;
				uint num22 = Pack.LE_To_UInt32(key, 4);
				array[0][1] = num22;
				uint num23 = Pack.LE_To_UInt32(key, 8);
				array[0][2] = num23;
				uint num24 = Pack.LE_To_UInt32(key, 12);
