					num21 ^= num25;
					array[l][0] = num21;
					num22 ^= num21;
					array[l][1] = num22;
					num23 ^= num22;
					array[l][2] = num23;
					num24 ^= num23;
					array[l][3] = num24;
				}
				break;
			}
			case 6:
			{
				uint num13 = Pack.LE_To_UInt32(key, 0);
				array[0][0] = num13;
				uint num14 = Pack.LE_To_UInt32(key, 4);
				array[0][1] = num14;
				uint num15 = Pack.LE_To_UInt32(key, 8);
				array[0][2] = num15;
				uint num16 = Pack.LE_To_UInt32(key, 12);
				array[0][3] = num16;
				uint num17 = Pack.LE_To_UInt32(key, 16);
				array[1][0] = num17;
