					num19 <<= 1;
					num13 ^= num20;
					array[k][0] = num13;
					num14 ^= num13;
					array[k][1] = num14;
					num15 ^= num14;
					array[k][2] = num15;
					num16 ^= num15;
					array[k][3] = num16;
					num17 ^= num16;
					array[k + 1][0] = num17;
					num18 ^= num17;
					array[k + 1][1] = num18;
					num20 = SubWord(Shift(num18, 8)) ^ num19;
					num19 <<= 1;
					num13 ^= num20;
					array[k + 1][2] = num13;
					num14 ^= num13;
					array[k + 1][3] = num14;
					num15 ^= num14;
					array[k + 2][0] = num15;
					num16 ^= num15;
					array[k + 2][1] = num16;
					num17 ^= num16;
					array[k + 2][2] = num17;
					num18 ^= num17;
					array[k + 2][3] = num18;
