					num4 ^= num3;
					array[j][1] = num4;
					num5 ^= num4;
					array[j][2] = num5;
					num6 ^= num5;
					array[j][3] = num6;
					num12 = SubWord(num6);
					num7 ^= num12;
					array[j + 1][0] = num7;
					num8 ^= num7;
					array[j + 1][1] = num8;
					num9 ^= num8;
					array[j + 1][2] = num9;
					num10 ^= num9;
					array[j + 1][3] = num10;
