			uint num4 = SBOX1[(byte)num3];
			num4 |= sbox4((byte)(num3 >> 8)) << 8;
			num4 |= sbox3((byte)(num3 >> 16)) << 16;
			num4 |= sbox2((byte)(num3 >> 24)) << 24;
			num4 = leftRotate(num4, 8);
