			Pack.LE_To_UInt32(ivBytes, 0, engineState, 13, 3);
		}

		protected override void GenerateKeyStream(byte[] output)
		{
			ChaChaEngine.ChachaCore(rounds, engineState, x);
			Pack.UInt32_To_LE(x, output, 0);
		}
	}
