				ulong num2 = internalState[1];
				ulong num3 = internalState[2];
				ulong num4 = internalState[3];
				ulong num5 = internalState[4];
				ulong num6 = internalState[5];
				ulong num7 = internalState[6];
				ulong num8 = internalState[7];
