				ulong num13 = internalState[3];
				ulong num14 = (num10 ^ num11) & 0xFFFF0000FFFF0000uL;
				num10 ^= num14;
				num11 ^= num14;
				num14 = (num12 ^ num13) & 0xFFFF0000FFFF0000uL;
				num12 ^= num14;
				num13 ^= num14;
				num14 = (num10 ^ num12) & 0xFFFFFFFF00000000uL;
				num10 ^= num14;
				num12 ^= num14;
				num14 = (num11 ^ num13) & 0xFFFFFFFF0000uL;
				num11 ^= num14;
				num13 ^= num14;
