				num ^= num9;
				num2 ^= num9;
				num9 = (num3 ^ num4) & 0xFF00FF00FF00FF00uL;
				num3 ^= num9;
				num4 ^= num9;
				num9 = (num5 ^ num6) & 0xFF00FF00FF00FF00uL;
				num5 ^= num9;
				num6 ^= num9;
				num9 = (num7 ^ num8) & 0xFF00FF00FF00FF00uL;
				num7 ^= num9;
				num8 ^= num9;
				num9 = (num ^ num3) & 0xFFFF0000FFFF0000uL;
