				num9 = (num2 ^ num4) & 0xFFFF0000FFFF00uL;
				num2 ^= num9;
				num4 ^= num9;
				num9 = (num5 ^ num7) & 0xFFFF0000FFFF0000uL;
				num5 ^= num9;
				num7 ^= num9;
				num9 = (num6 ^ num8) & 0xFFFF0000FFFF00uL;
				num6 ^= num9;
				num8 ^= num9;
