			int num2 = ((input[inOff + 5] & 0xFF) << 8) + (input[inOff + 4] & 0xFF);
			int num3 = ((input[inOff + 3] & 0xFF) << 8) + (input[inOff + 2] & 0xFF);
			int num4 = ((input[inOff + 1] & 0xFF) << 8) + (input[inOff] & 0xFF);
			for (int num5 = 60; num5 >= 44; num5 -= 4)
			{
