			sha1.DoFinal(digest, 0);
			byte[] array = new byte[8];
			Array.Copy(digest, 0, array, 0, 8);
			return array;
		}

		private bool CheckCmsKeyChecksum(byte[] key, byte[] checksum)
		{
			return Arrays.ConstantTimeAreEqual(CalculateCmsKeyChecksum(key), checksum);
		}
