			array[2] = (byte)(~array[5]);
			array[3] = (byte)(~array[6]);
			for (int i = 0; i < array.Length; i += blockSize)
			{
				engine.ProcessBlock(array, i, array, i);
			}
			for (int j = 0; j < array.Length; j += blockSize)
			{
				engine.ProcessBlock(array, j, array, j);
			}
