			X0 ^= wKey[124];
			X1 ^= wKey[125];
			X2 ^= wKey[126];
			X3 ^= wKey[127];
			InverseLT();
			Ib6(X0, X1, X2, X3);
			X0 ^= wKey[120];
			X1 ^= wKey[121];
			X2 ^= wKey[122];
			X3 ^= wKey[123];
			InverseLT();
			Ib5(X0, X1, X2, X3);
			X0 ^= wKey[116];
			X1 ^= wKey[117];
			X2 ^= wKey[118];
			X3 ^= wKey[119];
			InverseLT();
			Ib4(X0, X1, X2, X3);
			X0 ^= wKey[112];
			X1 ^= wKey[113];
			X2 ^= wKey[114];
			X3 ^= wKey[115];
			InverseLT();
