			X1 ^= wKey[53];
			X2 ^= wKey[54];
			X3 ^= wKey[55];
			InverseLT();
			Ib4(X0, X1, X2, X3);
			X0 ^= wKey[48];
			X1 ^= wKey[49];
			X2 ^= wKey[50];
			X3 ^= wKey[51];
			InverseLT();
			Ib3(X0, X1, X2, X3);
