		private int BytesTo32Bits(byte[] b, int p)
		{
			return (b[p] & 0xFF) | ((b[p + 1] & 0xFF) << 8) | ((b[p + 2] & 0xFF) << 16) | ((b[p + 3] & 0xFF) << 24);
		}

		private void Bits32ToBytes(int inData, byte[] b, int offset)
		{
