			byte b = P[(P[P[s & 0xFF] & 0xFF] + 1) & 0xFF];
			byte b2 = P[n & 0xFF];
			P[n & 0xFF] = P[s & 0xFF];
			P[s & 0xFF] = b2;
			n = (byte)((uint)(n + 1) & 0xFFu);
			return (byte)(input ^ b);
		}
	}
