			}
			if (keyBytes.Length != 32)
			{
				throw new ArgumentException(AlgorithmName + " requires a 256 bit key");
			}
			base.SetKey(keyBytes, ivBytes);
			Pack.LE_To_UInt32(ivBytes, 8, engineState, 8, 2);
