			byte[] array2 = new byte[4];
			int num = 0;
			digest.Reset();
			if (length > hLen)
			{
				do
				{
					ItoOSP(num, array2);
					digest.BlockUpdate(seed, 0, seed.Length);
					digest.BlockUpdate(array2, 0, array2.Length);
					digest.DoFinal(array, 0);
