				P[j & 0xFF] = P[s & 0xFF];
				P[s & 0xFF] = b2;
			}
			byte[] array = new byte[20];
			for (int k = 0; k < 20; k++)
			{
				s = P[(s + P[k & 0xFF]) & 0xFF];
				array[k] = P[(P[P[s & 0xFF] & 0xFF] + 1) & 0xFF];
				byte b3 = P[k & 0xFF];
				P[k & 0xFF] = P[s & 0xFF];
				P[s & 0xFF] = b3;
