			T[(g + 2) & 0x1F] = (byte)(T[(g + 2) & 0x1F] ^ x3);
			T[(g + 3) & 0x1F] = (byte)(T[(g + 3) & 0x1F] ^ x4);
			g = (byte)((uint)(g + 4) & 0x1Fu);
			byte b2 = P[n & 0xFF];
			P[n & 0xFF] = P[s & 0xFF];
			P[s & 0xFF] = b2;
