				}
				array = new byte[inLen - macSize];
			}
			ProcessPacket(input, inOff, inLen, array, 0);
			return array;
		}

		public virtual int ProcessPacket(byte[] input, int inOff, int inLen, byte[] output, int outOff)
		{
