					Array.Copy(input, inOff, buf, bufOff, num);
					num2 += cipher.ProcessBlock(buf, 0, output, outOff + num2);
					Array.Copy(buf, num, buf, 0, num);
					length -= num;
					inOff += num;
				}
			}
			Array.Copy(input, inOff, buf, bufOff, length);
