			Reset(clearMac: false);
			return num - macSize;
		}

		public virtual byte[] GetMac()
		{
			byte[] array = new byte[macSize];
			Array.Copy(macBlock, 0, array, 0, macSize);
			return array;
		}

		public virtual int GetUpdateOutputSize(int len)
		{
			int num = len + bufOff;
