			}
			return 0;
		}

		private bool VerifyMac(byte[] mac, int off)
		{
			int num = 0;
			for (int i = 0; i < macSize; i++)
			{
				num |= macBlock[i] ^ mac[off + i];
			}
			return num == 0;
