			Arrays.Fill(buffer, 0);
			Arrays.Fill(counter, 0);
			Arrays.Fill(macBlock, 0);
			counter[0] = 1;
			data.SetLength(0L);
			associatedText.SetLength(0L);
			if (initialAssociatedText != null)
			{
