		private readonly int blockSize;

		private readonly IBlockCipher cipher;

		public string AlgorithmName => cipher.AlgorithmName + "/KCTR";

		public bool IsPartialBlockOkay => true;

		public KCtrBlockCipher(IBlockCipher cipher)
		{
			this.cipher = cipher;
