	public class ECDomainParameters
	{
		private readonly Org.BouncyCastle.Math.EC.ECCurve curve;

		private readonly byte[] seed;

		private readonly Org.BouncyCastle.Math.EC.ECPoint g;

		private readonly BigInteger n;

		private readonly BigInteger h;

		private BigInteger hInv;

		public Org.BouncyCastle.Math.EC.ECCurve Curve => curve;

		public Org.BouncyCastle.Math.EC.ECPoint G => g;

		public BigInteger N => n;

		public BigInteger H => h;

		public BigInteger HInv
		{
			get
			{
				lock (this)
				{
					if (hInv == null)
					{
						hInv = h.ModInverse(n);
					}
					return hInv;
				}
			}
		}

		public ECDomainParameters(Org.BouncyCastle.Math.EC.ECCurve curve, Org.BouncyCastle.Math.EC.ECPoint g, BigInteger n)
			: this(curve, g, n, BigInteger.One, null)
		{
		}

		public ECDomainParameters(Org.BouncyCastle.Math.EC.ECCurve curve, Org.BouncyCastle.Math.EC.ECPoint g, BigInteger n, BigInteger h)
			: this(curve, g, n, h, null)
		{
		}

		public ECDomainParameters(Org.BouncyCastle.Math.EC.ECCurve curve, Org.BouncyCastle.Math.EC.ECPoint g, BigInteger n, BigInteger h, byte[] seed)
		{
			if (curve == null)
			{
				throw new ArgumentNullException("curve");
			}
			if (g == null)
			{
				throw new ArgumentNullException("g");
			}
			if (n == null)
			{
				throw new ArgumentNullException("n");
			}
			this.curve = curve;
			this.g = ValidatePublicPoint(curve, g);
			this.n = n;
			this.h = h;
			this.seed = Arrays.Clone(seed);
		}

		public byte[] GetSeed()
		{
			return Arrays.Clone(seed);
		}

		public override bool Equals(object obj)
		{
			if (obj == this)
			{
				return true;
			}
			if (!(obj is ECDomainParameters other))
			{
				return false;
			}
			return Equals(other);
		}

		protected virtual bool Equals(ECDomainParameters other)
		{
			if (curve.Equals(other.curve) && g.Equals(other.g))
			{
				return n.Equals(other.n);
			}
			return false;
		}

		public override int GetHashCode()
		{
			int num = 4;
			num *= 257;
			num ^= curve.GetHashCode();
			num *= 257;
			num ^= g.GetHashCode();
			num *= 257;
			return num ^ n.GetHashCode();
		}

		public BigInteger ValidatePrivateScalar(BigInteger d)
		{
			if (d == null)
			{
				throw new ArgumentNullException("d", "Scalar cannot be null");
			}
			if (d.CompareTo(BigInteger.One) < 0 || d.CompareTo(N) >= 0)
			{
				throw new ArgumentException("Scalar is not in the interval [1, n - 1]", "d");
			}
			return d;
		}

		public Org.BouncyCastle.Math.EC.ECPoint ValidatePublicPoint(Org.BouncyCastle.Math.EC.ECPoint q)
		{
			return ValidatePublicPoint(Curve, q);
		}

		internal static Org.BouncyCastle.Math.EC.ECPoint ValidatePublicPoint(Org.BouncyCastle.Math.EC.ECCurve c, Org.BouncyCastle.Math.EC.ECPoint q)
		{
			if (q == null)
			{
				throw new ArgumentNullException("q", "Point cannot be null");
			}
			q = ECAlgorithms.ImportPoint(c, q).Normalize();
			if (q.IsInfinity)
			{
				throw new ArgumentException("Point at infinity", "q");
			}
			if (!q.IsValid())
			{
				throw new ArgumentException("Point not on curve", "q");
			}
			return q;
		}
	}
