			public Builder(IDictionary paramsMap)
			{
				IEnumerator enumerator = paramsMap.Keys.GetEnumerator();
				while (enumerator.MoveNext())
				{
					int num = (int)enumerator.Current;
					parameters.Add(num, paramsMap[num]);
				}
