				{
					throw new ArgumentException("Parameter value must not be null.");
				}
				switch (type)
				{
				default:
					throw new ArgumentException("Parameter types must be in the range 0,5..47,49..62.");
				case 0:
				case 5:
				case 6:
				case 7:
				case 8:
				case 9:
				case 10:
				case 11:
				case 12:
				case 13:
				case 14:
				case 15:
				case 16:
				case 17:
				case 18:
				case 19:
