			}
			if (s.CompareTo(BigInteger.One) < 0 || s.CompareTo(n) >= 0)
			{
				return false;
			}
			byte[] message = DigestUtilities.DoFinal(digest);
			BigInteger bigInteger = CalculateE(n, message);
			BigInteger bigInteger2 = r.Add(s).Mod(n);
			if (bigInteger2.SignValue == 0)
			{
				return false;
			}
			Org.BouncyCastle.Math.EC.ECPoint q = ((ECPublicKeyParameters)ecKey).Q;
			Org.BouncyCastle.Math.EC.ECPoint eCPoint = ECAlgorithms.SumOfTwoMultiplies(ecParams.G, s, q, bigInteger2).Normalize();
			if (eCPoint.IsInfinity)
			{
