				{
				case 2:
				case 3:
				case 4:
				case 5:
				case 6:
				case 7:
				{
					if (mConnectionState < 3)
					{
						HandleSupplementalData(null);
					}
					if (mConnectionState < 4)
					{
						mKeyExchange.SkipServerCredentials();
						mAuthentication = null;
					}
					if (mConnectionState < 6)
					{
						mKeyExchange.SkipServerKeyExchange();
