					TlsProtocol.AssertEmpty(buf);
					mConnectionState = 8;
					mRecordStream.HandshakeHash.SealHashAlgorithms();
					IList clientSupplementalData = mTlsClient.GetClientSupplementalData();
					if (clientSupplementalData != null)
					{
