							SendCertificateMessage(Certificate.EmptyChain);
						}
						else
						{
							mKeyExchange.ProcessClientCredentials(tlsCredentials);
							SendCertificateMessage(tlsCredentials.Certificate);
						}
					}
					mConnectionState = 10;
					SendClientKeyExchangeMessage();
					mConnectionState = 11;
					if (TlsUtilities.IsSsl(Context))
					{
						TlsProtocol.EstablishMasterSecret(Context, mKeyExchange);
					}
					TlsHandshakeHash tlsHandshakeHash = mRecordStream.PrepareToFinish();
					mSecurityParameters.sessionHash = TlsProtocol.GetCurrentPrfHash(Context, tlsHandshakeHash, null);
					if (!TlsUtilities.IsSsl(Context))
					{
						TlsProtocol.EstablishMasterSecret(Context, mKeyExchange);
					}
					mRecordStream.SetPendingConnectionState(Peer.GetCompression(), Peer.GetCipher());
					if (tlsCredentials != null && tlsCredentials is TlsSignerCredentials)
					{
						TlsSignerCredentials tlsSignerCredentials = (TlsSignerCredentials)tlsCredentials;
						SignatureAndHashAlgorithm signatureAndHashAlgorithm = TlsUtilities.GetSignatureAndHashAlgorithm(Context, tlsSignerCredentials);
						byte[] hash = ((signatureAndHashAlgorithm != null) ? tlsHandshakeHash.GetFinalHash(signatureAndHashAlgorithm.Hash) : mSecurityParameters.SessionHash);
						byte[] signature = tlsSignerCredentials.GenerateCertificateSignature(hash);
						DigitallySigned certificateVerify = new DigitallySigned(signatureAndHashAlgorithm, signature);
						SendCertificateVerifyMessage(certificateVerify);
						mConnectionState = 12;
					}
					SendChangeCipherSpecMessage();
					SendFinishedMessage();
					mConnectionState = 13;
					break;
				}
				default:
					throw new TlsFatalAlert(10);
				}
				break;
			case 12:
				switch (mConnectionState)
				{
				case 2:
				case 3:
				case 4:
				case 5:
					if (mConnectionState < 3)
					{
						HandleSupplementalData(null);
					}
					if (mConnectionState < 4)
					{
						mKeyExchange.SkipServerCredentials();
						mAuthentication = null;
					}
					mKeyExchange.ProcessServerKeyExchange(buf);
					TlsProtocol.AssertEmpty(buf);
					mConnectionState = 6;
					break;
				default:
					throw new TlsFatalAlert(10);
				}
				break;
			case 13:
				switch (mConnectionState)
				{
				case 4:
				case 5:
				case 6:
					if (mConnectionState != 6)
					{
						mKeyExchange.SkipServerKeyExchange();
					}
					if (mAuthentication == null)
					{
						throw new TlsFatalAlert(40);
					}
					mCertificateRequest = CertificateRequest.Parse(Context, buf);
					TlsProtocol.AssertEmpty(buf);
					mKeyExchange.ValidateCertificateRequest(mCertificateRequest);
					TlsUtilities.TrackHashAlgorithms(mRecordStream.HandshakeHash, mCertificateRequest.SupportedSignatureAlgorithms);
					mConnectionState = 7;
					break;
				default:
					throw new TlsFatalAlert(10);
				}
				break;
			case 4:
			{
				short num = mConnectionState;
				if (num == 13)
				{
					if (!mExpectSessionTicket)
					{
						throw new TlsFatalAlert(10);
					}
					InvalidateSession();
					ReceiveNewSessionTicketMessage(buf);
					mConnectionState = 14;
					break;
				}
				throw new TlsFatalAlert(10);
			}
			case 0:
				TlsProtocol.AssertEmpty(buf);
				if (mConnectionState == 16)
				{
					RefuseRenegotiation();
				}
				break;
			default:
				throw new TlsFatalAlert(10);
			}
		}

		protected virtual void HandleSupplementalData(IList serverSupplementalData)
		{
			mTlsClient.ProcessServerSupplementalData(serverSupplementalData);
			mConnectionState = 3;
			mKeyExchange = mTlsClient.GetKeyExchange();
			mKeyExchange.Init(Context);
		}

		protected virtual void ReceiveNewSessionTicketMessage(MemoryStream buf)
		{
			NewSessionTicket newSessionTicket = NewSessionTicket.Parse(buf);
			TlsProtocol.AssertEmpty(buf);
			mTlsClient.NotifyNewSessionTicket(newSessionTicket);
		}

		protected virtual void ReceiveServerHelloMessage(MemoryStream buf)
		{
			ProtocolVersion protocolVersion = TlsUtilities.ReadVersion(buf);
			if (protocolVersion.IsDtls)
			{
				throw new TlsFatalAlert(47);
			}
			if (!protocolVersion.Equals(mRecordStream.ReadVersion))
			{
				throw new TlsFatalAlert(47);
			}
			ProtocolVersion clientVersion = Context.ClientVersion;
			if (!protocolVersion.IsEqualOrEarlierVersionOf(clientVersion))
			{
				throw new TlsFatalAlert(47);
			}
			mRecordStream.SetWriteVersion(protocolVersion);
			ContextAdmin.SetServerVersion(protocolVersion);
			mTlsClient.NotifyServerVersion(protocolVersion);
			mSecurityParameters.serverRandom = TlsUtilities.ReadFully(32, buf);
			mSelectedSessionID = TlsUtilities.ReadOpaque8(buf);
			if (mSelectedSessionID.Length > 32)
			{
				throw new TlsFatalAlert(47);
			}
			mTlsClient.NotifySessionID(mSelectedSessionID);
			mResumedSession = mSelectedSessionID.Length > 0 && mTlsSession != null && Arrays.AreEqual(mSelectedSessionID, mTlsSession.SessionID);
			int num = TlsUtilities.ReadUint16(buf);
			if (!Arrays.Contains(mOfferedCipherSuites, num) || num == 0 || CipherSuite.IsScsv(num) || !TlsUtilities.IsValidCipherSuiteForVersion(num, Context.ServerVersion))
			{
				throw new TlsFatalAlert(47);
			}
			mTlsClient.NotifySelectedCipherSuite(num);
			byte b = TlsUtilities.ReadUint8(buf);
			if (!Arrays.Contains(mOfferedCompressionMethods, b))
			{
				throw new TlsFatalAlert(47);
			}
			mTlsClient.NotifySelectedCompressionMethod(b);
			mServerExtensions = TlsProtocol.ReadExtensions(buf);
			mSecurityParameters.extendedMasterSecret = !TlsUtilities.IsSsl(mTlsClientContext) && TlsExtensionsUtilities.HasExtendedMasterSecretExtension(mServerExtensions);
			if (!mSecurityParameters.IsExtendedMasterSecret && (mResumedSession || mTlsClient.RequiresExtendedMasterSecret()))
			{
				throw new TlsFatalAlert(40);
			}
			if (mServerExtensions != null)
			{
				foreach (object key in mServerExtensions.Keys)
				{
					int num2 = (int)key;
					if (num2 != 65281)
					{
						if (TlsUtilities.GetExtensionData(mClientExtensions, num2) == null)
						{
							throw new TlsFatalAlert(110);
						}
						_ = mResumedSession;
					}
				}
			}
			byte[] extensionData = TlsUtilities.GetExtensionData(mServerExtensions, 65281);
			if (extensionData != null)
			{
				mSecureRenegotiation = true;
				if (!Arrays.ConstantTimeAreEqual(extensionData, TlsProtocol.CreateRenegotiationInfo(TlsUtilities.EmptyBytes)))
				{
					throw new TlsFatalAlert(40);
				}
			}
			mTlsClient.NotifySecureRenegotiation(mSecureRenegotiation);
			IDictionary dictionary = mClientExtensions;
			IDictionary dictionary2 = mServerExtensions;
			if (mResumedSession)
			{
				if (num != mSessionParameters.CipherSuite || b != mSessionParameters.CompressionAlgorithm)
				{
					throw new TlsFatalAlert(47);
				}
				dictionary = null;
				dictionary2 = mSessionParameters.ReadServerExtensions();
			}
			mSecurityParameters.cipherSuite = num;
			mSecurityParameters.compressionAlgorithm = b;
			if (dictionary2 != null && dictionary2.Count > 0)
			{
				bool flag = TlsExtensionsUtilities.HasEncryptThenMacExtension(dictionary2);
				if (flag && !TlsUtilities.IsBlockCipherSuite(num))
				{
					throw new TlsFatalAlert(47);
				}
				mSecurityParameters.encryptThenMac = flag;
				mSecurityParameters.maxFragmentLength = ProcessMaxFragmentLengthExtension(dictionary, dictionary2, 47);
				mSecurityParameters.truncatedHMac = TlsExtensionsUtilities.HasTruncatedHMacExtension(dictionary2);
				mAllowCertificateStatus = !mResumedSession && TlsUtilities.HasExpectedEmptyExtensionData(dictionary2, 5, 47);
				mExpectSessionTicket = !mResumedSession && TlsUtilities.HasExpectedEmptyExtensionData(dictionary2, 35, 47);
			}
			if (dictionary != null)
			{
				mTlsClient.ProcessServerExtensions(dictionary2);
			}
			mSecurityParameters.prfAlgorithm = TlsProtocol.GetPrfAlgorithm(Context, mSecurityParameters.CipherSuite);
			mSecurityParameters.verifyDataLength = 12;
		}

		protected virtual void SendCertificateVerifyMessage(DigitallySigned certificateVerify)
		{
			HandshakeMessage handshakeMessage = new HandshakeMessage(15);
			certificateVerify.Encode(handshakeMessage);
			handshakeMessage.WriteToRecordStream(this);
		}

		protected virtual void SendClientHelloMessage()
		{
			mRecordStream.SetWriteVersion(mTlsClient.ClientHelloRecordLayerVersion);
			ProtocolVersion clientVersion = mTlsClient.ClientVersion;
			if (clientVersion.IsDtls)
			{
				throw new TlsFatalAlert(80);
			}
			ContextAdmin.SetClientVersion(clientVersion);
			byte[] array = TlsUtilities.EmptyBytes;
			if (mTlsSession != null)
			{
				array = mTlsSession.SessionID;
				if (array == null || array.Length > 32)
				{
					array = TlsUtilities.EmptyBytes;
				}
			}
			bool isFallback = mTlsClient.IsFallback;
			mOfferedCipherSuites = mTlsClient.GetCipherSuites();
			mOfferedCompressionMethods = mTlsClient.GetCompressionMethods();
			if (array.Length > 0 && mSessionParameters != null && (!mSessionParameters.IsExtendedMasterSecret || !Arrays.Contains(mOfferedCipherSuites, mSessionParameters.CipherSuite) || !Arrays.Contains(mOfferedCompressionMethods, mSessionParameters.CompressionAlgorithm)))
			{
				array = TlsUtilities.EmptyBytes;
			}
			mClientExtensions = TlsExtensionsUtilities.EnsureExtensionsInitialised(mTlsClient.GetClientExtensions());
			if (!clientVersion.IsSsl)
			{
				TlsExtensionsUtilities.AddExtendedMasterSecretExtension(mClientExtensions);
			}
			HandshakeMessage handshakeMessage = new HandshakeMessage(1);
			TlsUtilities.WriteVersion(clientVersion, handshakeMessage);
			handshakeMessage.Write(mSecurityParameters.ClientRandom);
			TlsUtilities.WriteOpaque8(array, handshakeMessage);
			byte[] extensionData = TlsUtilities.GetExtensionData(mClientExtensions, 65281);
			bool flag = null == extensionData;
			bool flag2 = !Arrays.Contains(mOfferedCipherSuites, 255);
			if (flag && flag2)
			{
				mOfferedCipherSuites = Arrays.Append(mOfferedCipherSuites, 255);
			}
			if (isFallback && !Arrays.Contains(mOfferedCipherSuites, 22016))
			{
				mOfferedCipherSuites = Arrays.Append(mOfferedCipherSuites, 22016);
			}
			TlsUtilities.WriteUint16ArrayWithUint16Length(mOfferedCipherSuites, handshakeMessage);
			TlsUtilities.WriteUint8ArrayWithUint8Length(mOfferedCompressionMethods, handshakeMessage);
			TlsProtocol.WriteExtensions(handshakeMessage, mClientExtensions);
			handshakeMessage.WriteToRecordStream(this);
		}

		protected virtual void SendClientKeyExchangeMessage()
		{
			HandshakeMessage handshakeMessage = new HandshakeMessage(16);
			mKeyExchange.GenerateClientKeyExchange(handshakeMessage);
			handshakeMessage.WriteToRecordStream(this);
		}
	}
	public interface TlsCompression
	{
		Stream Compress(Stream output);

		Stream Decompress(Stream output);
	}
	public class TlsDeflateCompression : TlsCompression
	{
		protected class DeflateOutputStream : ZOutputStream
		{
			public DeflateOutputStream(Stream output, ZStream z, bool compress)
				: base(output, z)
			{
				base.compress = compress;
				FlushMode = 2;
			}

			public override void Flush()
			{
			}
		}

		public const int LEVEL_NONE = 0;

		public const int LEVEL_FASTEST = 1;

		public const int LEVEL_SMALLEST = 9;

		public const int LEVEL_DEFAULT = -1;

		protected readonly ZStream zIn;

		protected readonly ZStream zOut;

		public TlsDeflateCompression()
			: this(-1)
		{
		}

		public TlsDeflateCompression(int level)
		{
			zIn = new ZStream();
			zIn.inflateInit();
			zOut = new ZStream();
			zOut.deflateInit(level);
		}

		public virtual Stream Compress(Stream output)
		{
			return new DeflateOutputStream(output, zOut, compress: true);
		}

		public virtual Stream Decompress(Stream output)
		{
			return new DeflateOutputStream(output, zIn, compress: false);
		}
	}
}
namespace Org.BouncyCastle.Utilities.Zlib
{
	public class ZOutputStream : Stream
	{
		private const int BufferSize = 4096;

		protected ZStream z;

		protected int flushLevel = 0;

		protected byte[] buf = new byte[4096];

		protected byte[] buf1 = new byte[1];

		protected bool compress;

		protected Stream output;

		protected bool closed;

		public sealed override bool CanRead => false;

		public sealed override bool CanSeek => false;

		public sealed override bool CanWrite => !closed;

		public virtual int FlushMode
		{
			get
			{
				return flushLevel;
			}
			set
			{
				flushLevel = value;
			}
		}

		public sealed override long Length
		{
			get
			{
				throw new NotSupportedException();
			}
		}

		public sealed override long Position
		{
			get
			{
				throw new NotSupportedException();
			}
			set
			{
				throw new NotSupportedException();
			}
		}

		public virtual long TotalIn => z.total_in;

		public virtual long TotalOut => z.total_out;

		private static ZStream GetDefaultZStream(bool nowrap)
		{
			ZStream zStream = new ZStream();
			zStream.inflateInit(nowrap);
			return zStream;
		}

		public ZOutputStream(Stream output)
			: this(output, nowrap: false)
		{
		}

		public ZOutputStream(Stream output, bool nowrap)
			: this(output, GetDefaultZStream(nowrap))
		{
		}

		public ZOutputStream(Stream output, ZStream z)
		{
			if (z == null)
			{
				z = new ZStream();
			}
			if (z.istate == null && z.dstate == null)
			{
				z.inflateInit();
			}
			this.output = output;
			compress = z.istate == null;
			this.z = z;
		}

		public ZOutputStream(Stream output, int level)
			: this(output, level, nowrap: false)
		{
		}

		public ZOutputStream(Stream output, int level, bool nowrap)
		{
			this.output = output;
			compress = true;
			z = new ZStream();
			z.deflateInit(level, nowrap);
		}

		public override void Close()
		{
			if (!closed)
			{
				DoClose();
				base.Close();
			}
		}

		private void DoClose()
		{
			try
			{
				Finish();
			}
			catch (IOException)
			{
			}
			finally
			{
				closed = true;
				End();
				Platform.Dispose(output);
				output = null;
			}
		}

		public virtual void End()
		{
			if (z != null)
			{
				if (compress)
				{
					z.deflateEnd();
				}
				else
				{
					z.inflateEnd();
				}
				z.free();
				z = null;
			}
		}

		public virtual void Finish()
		{
			do
			{
				z.next_out = buf;
				z.next_out_index = 0;
				z.avail_out = buf.Length;
				int num = (compress ? z.deflate(4) : z.inflate(4));
				if (num != 1 && num != 0)
				{
					throw new IOException((compress ? "de" : "in") + "flating: " + z.msg);
				}
				int num2 = buf.Length - z.avail_out;
				if (num2 > 0)
				{
					output.Write(buf, 0, num2);
				}
			}
			while (z.avail_in > 0 || z.avail_out == 0);
			Flush();
		}

		public override void Flush()
		{
			output.Flush();
		}

		public sealed override int Read(byte[] buffer, int offset, int count)
		{
			throw new NotSupportedException();
		}

		public sealed override long Seek(long offset, SeekOrigin origin)
		{
			throw new NotSupportedException();
		}

		public sealed override void SetLength(long value)
		{
			throw new NotSupportedException();
		}

		public override void Write(byte[] b, int off, int len)
		{
			if (len == 0)
			{
				return;
			}
			z.next_in = b;
			z.next_in_index = off;
			z.avail_in = len;
			do
			{
				z.next_out = buf;
				z.next_out_index = 0;
				z.avail_out = buf.Length;
				if ((compress ? z.deflate(flushLevel) : z.inflate(flushLevel)) != 0)
				{
					throw new IOException((compress ? "de" : "in") + "flating: " + z.msg);
				}
				output.Write(buf, 0, buf.Length - z.avail_out);
			}
			while (z.avail_in > 0 || z.avail_out == 0);
		}

		public override void WriteByte(byte b)
		{
			buf1[0] = b;
			Write(buf1, 0, 1);
		}
	}
}
namespace Org.BouncyCastle.Crypto.Tls
{
	public class TlsDHKeyExchange : AbstractTlsKeyExchange
	{
		protected TlsSigner mTlsSigner;

		protected TlsDHVerifier mDHVerifier;

		protected DHParameters mDHParameters;

		protected AsymmetricKeyParameter mServerPublicKey;

		protected TlsAgreementCredentials mAgreementCredentials;

		protected DHPrivateKeyParameters mDHAgreePrivateKey;

		protected DHPublicKeyParameters mDHAgreePublicKey;

		public override bool RequiresServerKeyExchange
		{
			get
			{
				switch (mKeyExchange)
				{
				case 3:
				case 5:
				case 11:
					return true;
				default:
					return false;
				}
			}
		}

		[Obsolete("Use constructor that takes a TlsDHVerifier")]
		public TlsDHKeyExchange(int keyExchange, IList supportedSignatureAlgorithms, DHParameters dhParameters)
			: this(keyExchange, supportedSignatureAlgorithms, new DefaultTlsDHVerifier(), dhParameters)
		{
		}

		public TlsDHKeyExchange(int keyExchange, IList supportedSignatureAlgorithms, TlsDHVerifier dhVerifier, DHParameters dhParameters)
			: base(keyExchange, supportedSignatureAlgorithms)
		{
			switch (keyExchange)
			{
			case 7:
			case 9:
			case 11:
				mTlsSigner = null;
				break;
			case 5:
				mTlsSigner = new TlsRsaSigner();
				break;
			case 3:
				mTlsSigner = new TlsDssSigner();
				break;
			default:
				throw new InvalidOperationException("unsupported key exchange algorithm");
			}
			mDHVerifier = dhVerifier;
			mDHParameters = dhParameters;
		}

		public override void Init(TlsContext context)
		{
			base.Init(context);
			if (mTlsSigner != null)
			{
				mTlsSigner.Init(context);
			}
		}

		public override void SkipServerCredentials()
		{
			if (mKeyExchange != 11)
			{
				throw new TlsFatalAlert(10);
			}
		}

		public override void ProcessServerCertificate(Certificate serverCertificate)
		{
			if (mKeyExchange == 11)
			{
				throw new TlsFatalAlert(10);
			}
			if (serverCertificate.IsEmpty)
			{
				throw new TlsFatalAlert(42);
			}
			X509CertificateStructure certificateAt = serverCertificate.GetCertificateAt(0);
			SubjectPublicKeyInfo subjectPublicKeyInfo = certificateAt.SubjectPublicKeyInfo;
			try
			{
				mServerPublicKey = PublicKeyFactory.CreateKey(subjectPublicKeyInfo);
			}
			catch (Exception alertCause)
			{
				throw new TlsFatalAlert(43, alertCause);
			}
			if (mTlsSigner == null)
			{
				try
				{
					mDHAgreePublicKey = (DHPublicKeyParameters)mServerPublicKey;
					mDHParameters = mDHAgreePublicKey.Parameters;
				}
				catch (InvalidCastException alertCause2)
				{
					throw new TlsFatalAlert(46, alertCause2);
				}
				TlsUtilities.ValidateKeyUsage(certificateAt, 8);
			}
			else
			{
				if (!mTlsSigner.IsValidPublicKey(mServerPublicKey))
				{
					throw new TlsFatalAlert(46);
				}
				TlsUtilities.ValidateKeyUsage(certificateAt, 128);
			}
			base.ProcessServerCertificate(serverCertificate);
		}

		public override byte[] GenerateServerKeyExchange()
		{
			if (!RequiresServerKeyExchange)
			{
				return null;
			}
			MemoryStream memoryStream = new MemoryStream();
			mDHAgreePrivateKey = TlsDHUtilities.GenerateEphemeralServerKeyExchange(mContext.SecureRandom, mDHParameters, memoryStream);
			return memoryStream.ToArray();
		}

		public override void ProcessServerKeyExchange(Stream input)
		{
			if (!RequiresServerKeyExchange)
			{
				throw new TlsFatalAlert(10);
			}
			mDHParameters = TlsDHUtilities.ReceiveDHParameters(mDHVerifier, input);
			mDHAgreePublicKey = new DHPublicKeyParameters(TlsDHUtilities.ReadDHParameter(input), mDHParameters);
		}

		public override void ValidateCertificateRequest(CertificateRequest certificateRequest)
		{
			if (mKeyExchange == 11)
			{
				throw new TlsFatalAlert(40);
			}
			byte[] certificateTypes = certificateRequest.CertificateTypes;
			for (int i = 0; i < certificateTypes.Length; i++)
			{
				switch (certificateTypes[i])
				{
				case 1:
				case 2:
				case 3:
				case 4:
				case 64:
					continue;
				}
				throw new TlsFatalAlert(47);
			}
		}

		public override void ProcessClientCredentials(TlsCredentials clientCredentials)
		{
			if (mKeyExchange == 11)
			{
				throw new TlsFatalAlert(80);
			}
			if (clientCredentials is TlsAgreementCredentials)
			{
				mAgreementCredentials = (TlsAgreementCredentials)clientCredentials;
			}
			else if (!(clientCredentials is TlsSignerCredentials))
			{
				throw new TlsFatalAlert(80);
			}
		}

		public override void GenerateClientKeyExchange(Stream output)
		{
			if (mAgreementCredentials == null)
			{
				mDHAgreePrivateKey = TlsDHUtilities.GenerateEphemeralClientKeyExchange(mContext.SecureRandom, mDHParameters, output);
			}
		}

		public override void ProcessClientCertificate(Certificate clientCertificate)
		{
			if (mKeyExchange == 11)
			{
				throw new TlsFatalAlert(10);
			}
		}

		public override void ProcessClientKeyExchange(Stream input)
		{
			if (mDHAgreePublicKey == null)
			{
				mDHAgreePublicKey = new DHPublicKeyParameters(TlsDHUtilities.ReadDHParameter(input), mDHParameters);
			}
		}

		public override byte[] GeneratePremasterSecret()
		{
			if (mAgreementCredentials != null)
			{
				return mAgreementCredentials.GenerateAgreement(mDHAgreePublicKey);
			}
			if (mDHAgreePrivateKey != null)
			{
				return TlsDHUtilities.CalculateDHBasicAgreement(mDHAgreePublicKey, mDHAgreePrivateKey);
			}
			throw new TlsFatalAlert(80);
		}
	}
	public class TlsDheKeyExchange : TlsDHKeyExchange
	{
		protected TlsSignerCredentials mServerCredentials = null;

		[Obsolete("Use constructor that takes a TlsDHVerifier")]
		public TlsDheKeyExchange(int keyExchange, IList supportedSignatureAlgorithms, DHParameters dhParameters)
			: this(keyExchange, supportedSignatureAlgorithms, new DefaultTlsDHVerifier(), dhParameters)
		{
		}

		public TlsDheKeyExchange(int keyExchange, IList supportedSignatureAlgorithms, TlsDHVerifier dhVerifier, DHParameters dhParameters)
			: base(keyExchange, supportedSignatureAlgorithms, dhVerifier, dhParameters)
		{
		}

		public override void ProcessServerCredentials(TlsCredentials serverCredentials)
		{
			if (!(serverCredentials is TlsSignerCredentials))
			{
				throw new TlsFatalAlert(80);
			}
			ProcessServerCertificate(serverCredentials.Certificate);
			mServerCredentials = (TlsSignerCredentials)serverCredentials;
		}

		public override byte[] GenerateServerKeyExchange()
		{
			if (mDHParameters == null)
			{
				throw new TlsFatalAlert(80);
			}
			DigestInputBuffer digestInputBuffer = new DigestInputBuffer();
			mDHAgreePrivateKey = TlsDHUtilities.GenerateEphemeralServerKeyExchange(mContext.SecureRandom, mDHParameters, digestInputBuffer);
			SignatureAndHashAlgorithm signatureAndHashAlgorithm = TlsUtilities.GetSignatureAndHashAlgorithm(mContext, mServerCredentials);
			IDigest digest = TlsUtilities.CreateHash(signatureAndHashAlgorithm);
			SecurityParameters securityParameters = mContext.SecurityParameters;
			digest.BlockUpdate(securityParameters.clientRandom, 0, securityParameters.clientRandom.Length);
			digest.BlockUpdate(securityParameters.serverRandom, 0, securityParameters.serverRandom.Length);
			digestInputBuffer.UpdateDigest(digest);
			byte[] hash = DigestUtilities.DoFinal(digest);
			byte[] signature = mServerCredentials.GenerateCertificateSignature(hash);
			DigitallySigned digitallySigned = new DigitallySigned(signatureAndHashAlgorithm, signature);
			digitallySigned.Encode(digestInputBuffer);
			return digestInputBuffer.ToArray();
		}

		public override void ProcessServerKeyExchange(Stream input)
		{
			SecurityParameters securityParameters = mContext.SecurityParameters;
			SignerInputBuffer signerInputBuffer = new SignerInputBuffer();
			Stream input2 = new TeeInputStream(input, signerInputBuffer);
			mDHParameters = TlsDHUtilities.ReceiveDHParameters(mDHVerifier, input2);
			mDHAgreePublicKey = new DHPublicKeyParameters(TlsDHUtilities.ReadDHParameter(input2), mDHParameters);
			DigitallySigned digitallySigned = ParseSignature(input);
			ISigner signer = InitVerifyer(mTlsSigner, digitallySigned.Algorithm, securityParameters);
			signerInputBuffer.UpdateSigner(signer);
			if (!signer.VerifySignature(digitallySigned.Signature))
			{
				throw new TlsFatalAlert(51);
			}
		}

		protected virtual ISigner InitVerifyer(TlsSigner tlsSigner, SignatureAndHashAlgorithm algorithm, SecurityParameters securityParameters)
		{
			ISigner signer = tlsSigner.CreateVerifyer(algorithm, mServerPublicKey);
			signer.BlockUpdate(securityParameters.clientRandom, 0, securityParameters.clientRandom.Length);
			signer.BlockUpdate(securityParameters.serverRandom, 0, securityParameters.serverRandom.Length);
			return signer;
		}
	}
	public abstract class TlsDHUtilities
	{
		internal static readonly BigInteger Two = BigInteger.Two;

		private static readonly string draft_ffdhe2432_p = "";

		internal static readonly DHParameters draft_ffdhe2432 = FromSafeP(draft_ffdhe2432_p);

		private static readonly string draft_ffdhe3072_p = "";

		internal static readonly DHParameters draft_ffdhe3072 = FromSafeP(draft_ffdhe3072_p);

		private static readonly string draft_ffdhe4096_p = "";

		internal static readonly DHParameters draft_ffdhe4096 = FromSafeP(draft_ffdhe4096_p);

		private static readonly string draft_ffdhe6144_p = "";

		internal static readonly DHParameters draft_ffdhe6144 = FromSafeP(draft_ffdhe6144_p);

		private static readonly string draft_ffdhe8192_p = "";

		internal static readonly DHParameters draft_ffdhe8192 = FromSafeP(draft_ffdhe8192_p);

		private static BigInteger FromHex(string hex)
		{
			return new BigInteger(1, Hex.DecodeStrict(hex));
		}

		private static DHParameters FromSafeP(string hexP)
		{
			BigInteger bigInteger = FromHex(hexP);
			BigInteger q = bigInteger.ShiftRight(1);
			return new DHParameters(bigInteger, Two, q);
		}

		public static void AddNegotiatedDheGroupsClientExtension(IDictionary extensions, byte[] dheGroups)
		{
			extensions[ExtensionType.negotiated_ff_dhe_groups] = CreateNegotiatedDheGroupsClientExtension(dheGroups);
		}

		public static void AddNegotiatedDheGroupsServerExtension(IDictionary extensions, byte dheGroup)
		{
			extensions[ExtensionType.negotiated_ff_dhe_groups] = CreateNegotiatedDheGroupsServerExtension(dheGroup);
		}

		public static byte[] GetNegotiatedDheGroupsClientExtension(IDictionary extensions)
		{
			byte[] extensionData = TlsUtilities.GetExtensionData(extensions, ExtensionType.negotiated_ff_dhe_groups);
			if (extensionData != null)
			{
				return ReadNegotiatedDheGroupsClientExtension(extensionData);
			}
			return null;
		}

		public static short GetNegotiatedDheGroupsServerExtension(IDictionary extensions)
		{
			byte[] extensionData = TlsUtilities.GetExtensionData(extensions, ExtensionType.negotiated_ff_dhe_groups);
			if (extensionData != null)
			{
				return ReadNegotiatedDheGroupsServerExtension(extensionData);
			}
			return -1;
		}

		public static byte[] CreateNegotiatedDheGroupsClientExtension(byte[] dheGroups)
		{
			if (dheGroups == null || dheGroups.Length < 1 || dheGroups.Length > 255)
			{
				throw new TlsFatalAlert(80);
			}
			return TlsUtilities.EncodeUint8ArrayWithUint8Length(dheGroups);
		}

		public static byte[] CreateNegotiatedDheGroupsServerExtension(byte dheGroup)
		{
			return TlsUtilities.EncodeUint8(dheGroup);
		}

		public static byte[] ReadNegotiatedDheGroupsClientExtension(byte[] extensionData)
		{
			byte[] array = TlsUtilities.DecodeUint8ArrayWithUint8Length(extensionData);
			if (array.Length < 1)
			{
				throw new TlsFatalAlert(50);
			}
			return array;
		}

		public static byte ReadNegotiatedDheGroupsServerExtension(byte[] extensionData)
		{
			return TlsUtilities.DecodeUint8(extensionData);
		}

		public static DHParameters GetParametersForDHEGroup(short dheGroup)
		{
			return dheGroup switch
			{
				0 => draft_ffdhe2432, 
				1 => draft_ffdhe3072, 
				2 => draft_ffdhe4096, 
				3 => draft_ffdhe6144, 
				4 => draft_ffdhe8192, 
				_ => null, 
			};
		}

		public static bool ContainsDheCipherSuites(int[] cipherSuites)
		{
			for (int i = 0; i < cipherSuites.Length; i++)
			{
				if (IsDheCipherSuite(cipherSuites[i]))
				{
					return true;
