		public static bool AreCompatibleParameters(DHParameters a, DHParameters b)
		{
			if (a.P.Equals(b.P) && a.G.Equals(b.G))
			{
				if (a.Q != null && b.Q != null)
				{
					return a.Q.Equals(b.Q);
				}
				return true;
			}
			return false;
		}

		public static byte[] CalculateDHBasicAgreement(DHPublicKeyParameters publicKey, DHPrivateKeyParameters privateKey)
		{
			DHBasicAgreement dHBasicAgreement = new DHBasicAgreement();
			dHBasicAgreement.Init(privateKey);
			BigInteger n = dHBasicAgreement.CalculateAgreement(publicKey);
			return BigIntegers.AsUnsignedByteArray(n);
		}

		public static AsymmetricCipherKeyPair GenerateDHKeyPair(SecureRandom random, DHParameters dhParams)
		{
			DHBasicKeyPairGenerator dHBasicKeyPairGenerator = new DHBasicKeyPairGenerator();
			dHBasicKeyPairGenerator.Init(new DHKeyGenerationParameters(random, dhParams));
			return dHBasicKeyPairGenerator.GenerateKeyPair();
		}

		public static DHPrivateKeyParameters GenerateEphemeralClientKeyExchange(SecureRandom random, DHParameters dhParams, Stream output)
		{
			AsymmetricCipherKeyPair asymmetricCipherKeyPair = GenerateDHKeyPair(random, dhParams);
			DHPublicKeyParameters dHPublicKeyParameters = (DHPublicKeyParameters)asymmetricCipherKeyPair.Public;
			WriteDHParameter(dHPublicKeyParameters.Y, output);
			return (DHPrivateKeyParameters)asymmetricCipherKeyPair.Private;
		}

		public static DHPrivateKeyParameters GenerateEphemeralServerKeyExchange(SecureRandom random, DHParameters dhParams, Stream output)
		{
			AsymmetricCipherKeyPair asymmetricCipherKeyPair = GenerateDHKeyPair(random, dhParams);
			DHPublicKeyParameters dHPublicKeyParameters = (DHPublicKeyParameters)asymmetricCipherKeyPair.Public;
			WriteDHParameters(dhParams, output);
			WriteDHParameter(dHPublicKeyParameters.Y, output);
			return (DHPrivateKeyParameters)asymmetricCipherKeyPair.Private;
		}

		public static BigInteger ReadDHParameter(Stream input)
		{
			return new BigInteger(1, TlsUtilities.ReadOpaque16(input));
		}

		public static DHParameters ReadDHParameters(Stream input)
		{
			BigInteger p = ReadDHParameter(input);
			BigInteger g = ReadDHParameter(input);
			return new DHParameters(p, g);
		}

		public static DHParameters ReceiveDHParameters(TlsDHVerifier dhVerifier, Stream input)
		{
			DHParameters dHParameters = ReadDHParameters(input);
			if (!dhVerifier.Accept(dHParameters))
			{
				throw new TlsFatalAlert(71);
			}
			return dHParameters;
		}

		public static void WriteDHParameter(BigInteger x, Stream output)
		{
			TlsUtilities.WriteOpaque16(BigIntegers.AsUnsignedByteArray(x), output);
		}

		public static void WriteDHParameters(DHParameters dhParameters, Stream output)
		{
			WriteDHParameter(dhParameters.P, output);
			WriteDHParameter(dhParameters.G, output);
		}
	}
	public abstract class TlsDsaSigner : AbstractTlsSigner
	{
		protected abstract byte SignatureAlgorithm { get; }

		public override byte[] GenerateRawSignature(SignatureAndHashAlgorithm algorithm, AsymmetricKeyParameter privateKey, byte[] hash)
		{
			ISigner signer = MakeSigner(algorithm, raw: true, forSigning: true, new ParametersWithRandom(privateKey, mContext.SecureRandom));
			if (algorithm == null)
			{
				signer.BlockUpdate(hash, 16, 20);
			}
			else
			{
				signer.BlockUpdate(hash, 0, hash.Length);
			}
			return signer.GenerateSignature();
		}

		public override bool VerifyRawSignature(SignatureAndHashAlgorithm algorithm, byte[] sigBytes, AsymmetricKeyParameter publicKey, byte[] hash)
		{
			ISigner signer = MakeSigner(algorithm, raw: true, forSigning: false, publicKey);
			if (algorithm == null)
			{
				signer.BlockUpdate(hash, 16, 20);
			}
			else
			{
				signer.BlockUpdate(hash, 0, hash.Length);
			}
			return signer.VerifySignature(sigBytes);
		}

		public override ISigner CreateSigner(SignatureAndHashAlgorithm algorithm, AsymmetricKeyParameter privateKey)
		{
			return MakeSigner(algorithm, raw: false, forSigning: true, privateKey);
		}

		public override ISigner CreateVerifyer(SignatureAndHashAlgorithm algorithm, AsymmetricKeyParameter publicKey)
		{
			return MakeSigner(algorithm, raw: false, forSigning: false, publicKey);
		}

		protected virtual ICipherParameters MakeInitParameters(bool forSigning, ICipherParameters cp)
		{
			return cp;
		}

		protected virtual ISigner MakeSigner(SignatureAndHashAlgorithm algorithm, bool raw, bool forSigning, ICipherParameters cp)
		{
			if (algorithm != null != TlsUtilities.IsTlsV12(mContext))
			{
				throw new InvalidOperationException();
			}
			if (algorithm != null && algorithm.Signature != SignatureAlgorithm)
			{
				throw new InvalidOperationException();
			}
			byte hashAlgorithm = algorithm?.Hash ?? 2;
			IDigest digest = (raw ? new NullDigest() : TlsUtilities.CreateHash(hashAlgorithm));
			ISigner signer = new DsaDigestSigner(CreateDsaImpl(hashAlgorithm), digest);
			signer.Init(forSigning, MakeInitParameters(forSigning, cp));
			return signer;
		}

		protected abstract IDsa CreateDsaImpl(byte hashAlgorithm);
	}
	public class TlsDssSigner : TlsDsaSigner
	{
		protected override byte SignatureAlgorithm => 2;

		public override bool IsValidPublicKey(AsymmetricKeyParameter publicKey)
		{
			return publicKey is DsaPublicKeyParameters;
		}

		protected override IDsa CreateDsaImpl(byte hashAlgorithm)
		{
			return new DsaSigner(new HMacDsaKCalculator(TlsUtilities.CreateHash(hashAlgorithm)));
		}
	}
	public abstract class TlsEccUtilities
	{
		private static readonly string[] CurveNames = new string[28]
		{
			"sect163k1", "sect163r1", "sect163r2", "sect193r1", "sect193r2", "sect233k1", "sect233r1", "sect239k1", "sect283k1", "sect283r1",
			"sect409k1", "sect409r1", "sect571k1", "sect571r1", "secp160k1", "secp160r1", "secp160r2", "secp192k1", "secp192r1", "secp224k1",
			"secp224r1", "secp256k1", "secp256r1", "secp384r1", "secp521r1", "brainpoolP256r1", "brainpoolP384r1", "brainpoolP512r1"
		};

		public static void AddSupportedEllipticCurvesExtension(IDictionary extensions, int[] namedCurves)
		{
			extensions[10] = CreateSupportedEllipticCurvesExtension(namedCurves);
		}

		public static void AddSupportedPointFormatsExtension(IDictionary extensions, byte[] ecPointFormats)
		{
			extensions[11] = CreateSupportedPointFormatsExtension(ecPointFormats);
		}

		public static int[] GetSupportedEllipticCurvesExtension(IDictionary extensions)
		{
			byte[] extensionData = TlsUtilities.GetExtensionData(extensions, 10);
			if (extensionData != null)
			{
				return ReadSupportedEllipticCurvesExtension(extensionData);
			}
			return null;
		}

		public static byte[] GetSupportedPointFormatsExtension(IDictionary extensions)
		{
			byte[] extensionData = TlsUtilities.GetExtensionData(extensions, 11);
			if (extensionData != null)
			{
				return ReadSupportedPointFormatsExtension(extensionData);
			}
			return null;
		}

		public static byte[] CreateSupportedEllipticCurvesExtension(int[] namedCurves)
		{
			if (namedCurves == null || namedCurves.Length < 1)
			{
				throw new TlsFatalAlert(80);
			}
			return TlsUtilities.EncodeUint16ArrayWithUint16Length(namedCurves);
		}

		public static byte[] CreateSupportedPointFormatsExtension(byte[] ecPointFormats)
		{
			if (ecPointFormats == null || !Arrays.Contains(ecPointFormats, 0))
			{
				ecPointFormats = Arrays.Append(ecPointFormats, 0);
			}
			return TlsUtilities.EncodeUint8ArrayWithUint8Length(ecPointFormats);
		}

		public static int[] ReadSupportedEllipticCurvesExtension(byte[] extensionData)
		{
			if (extensionData == null)
			{
				throw new ArgumentNullException("extensionData");
			}
			MemoryStream memoryStream = new MemoryStream(extensionData, writable: false);
			int num = TlsUtilities.ReadUint16(memoryStream);
			if (num < 2 || ((uint)num & (true ? 1u : 0u)) != 0)
			{
				throw new TlsFatalAlert(50);
			}
			int[] result = TlsUtilities.ReadUint16Array(num / 2, memoryStream);
			TlsProtocol.AssertEmpty(memoryStream);
			return result;
		}

		public static byte[] ReadSupportedPointFormatsExtension(byte[] extensionData)
		{
			byte[] array = TlsUtilities.DecodeUint8ArrayWithUint8Length(extensionData);
			if (!Arrays.Contains(array, 0))
			{
				throw new TlsFatalAlert(47);
			}
			return array;
		}

		public static string GetNameOfNamedCurve(int namedCurve)
		{
			if (!IsSupportedNamedCurve(namedCurve))
			{
				return null;
			}
			return CurveNames[namedCurve - 1];
		}

		public static ECDomainParameters GetParametersForNamedCurve(int namedCurve)
		{
			string nameOfNamedCurve = GetNameOfNamedCurve(namedCurve);
			if (nameOfNamedCurve == null)
			{
				return null;
			}
			X9ECParameters byName = CustomNamedCurves.GetByName(nameOfNamedCurve);
			if (byName == null)
			{
				byName = ECNamedCurveTable.GetByName(nameOfNamedCurve);
				if (byName == null)
				{
					return null;
				}
			}
			return new ECDomainParameters(byName.Curve, byName.G, byName.N, byName.H, byName.GetSeed());
		}

		public static bool HasAnySupportedNamedCurves()
		{
			return CurveNames.Length > 0;
		}

		public static bool ContainsEccCipherSuites(int[] cipherSuites)
		{
			for (int i = 0; i < cipherSuites.Length; i++)
			{
				if (IsEccCipherSuite(cipherSuites[i]))
				{
					return true;
				}
			}
			return false;
		}

