				ECDomainParameters parameters = mECAgreePrivateKey.Parameters;
				mECAgreePublicKey = TlsEccUtilities.ValidateECPublicKey(TlsEccUtilities.DeserializeECPublicKey(mServerECPointFormats, parameters, encoding));
			}
