		{
			if (41 == alertDescription && mCertificateRequest != null && TlsUtilities.IsSsl(mTlsServerContext))
			{
				switch (mConnectionState)
				{
				case 8:
				case 9:
					if (mConnectionState < 9)
					{
						mTlsServer.ProcessClientSupplementalData(null);
					}
					NotifyClientCertificate(Certificate.EmptyChain);
					mConnectionState = 10;
					return;
				}
			}
			base.HandleAlertWarningMessage(alertDescription);
		}

		protected virtual void NotifyClientCertificate(Certificate clientCertificate)
		{
			if (mCertificateRequest == null)
			{
				throw new InvalidOperationException();
			}
			if (mPeerCertificate != null)
			{
				throw new TlsFatalAlert(10);
			}
			mPeerCertificate = clientCertificate;
			if (clientCertificate.IsEmpty)
			{
				mKeyExchange.SkipClientCredentials();
			}
			else
			{
				mClientCertificateType = TlsUtilities.GetClientCertificateType(clientCertificate, mServerCredentials.Certificate);
				mKeyExchange.ProcessClientCertificate(clientCertificate);
			}
			mTlsServer.NotifyClientCertificate(clientCertificate);
		}

		protected virtual void ReceiveCertificateMessage(MemoryStream buf)
		{
			Certificate clientCertificate = Certificate.Parse(buf);
			TlsProtocol.AssertEmpty(buf);
			NotifyClientCertificate(clientCertificate);
		}

		protected virtual void ReceiveCertificateVerifyMessage(MemoryStream buf)
		{
			if (mCertificateRequest == null)
			{
				throw new InvalidOperationException();
			}
			DigitallySigned digitallySigned = DigitallySigned.Parse(Context, buf);
			TlsProtocol.AssertEmpty(buf);
			try
			{
				SignatureAndHashAlgorithm algorithm = digitallySigned.Algorithm;
				byte[] hash;
				if (TlsUtilities.IsTlsV12(Context))
				{
					TlsUtilities.VerifySupportedSignatureAlgorithm(mCertificateRequest.SupportedSignatureAlgorithms, algorithm);
					hash = mPrepareFinishHash.GetFinalHash(algorithm.Hash);
				}
				else
				{
					hash = mSecurityParameters.SessionHash;
				}
				X509CertificateStructure certificateAt = mPeerCertificate.GetCertificateAt(0);
				SubjectPublicKeyInfo subjectPublicKeyInfo = certificateAt.SubjectPublicKeyInfo;
				AsymmetricKeyParameter publicKey = PublicKeyFactory.CreateKey(subjectPublicKeyInfo);
				TlsSigner tlsSigner = TlsUtilities.CreateTlsSigner((byte)mClientCertificateType);
				tlsSigner.Init(Context);
				if (!tlsSigner.VerifyRawSignature(algorithm, digitallySigned.Signature, publicKey, hash))
				{
					throw new TlsFatalAlert(51);
				}
			}
			catch (TlsFatalAlert tlsFatalAlert)
			{
				throw tlsFatalAlert;
			}
			catch (Exception alertCause)
			{
				throw new TlsFatalAlert(51, alertCause);
			}
		}

		protected virtual void ReceiveClientHelloMessage(MemoryStream buf)
		{
			ProtocolVersion protocolVersion = TlsUtilities.ReadVersion(buf);
			mRecordStream.SetWriteVersion(protocolVersion);
			if (protocolVersion.IsDtls)
			{
				throw new TlsFatalAlert(47);
			}
			byte[] clientRandom = TlsUtilities.ReadFully(32, buf);
			byte[] array = TlsUtilities.ReadOpaque8(buf);
			if (array.Length > 32)
			{
				throw new TlsFatalAlert(47);
			}
			int num = TlsUtilities.ReadUint16(buf);
			if (num < 2 || ((uint)num & (true ? 1u : 0u)) != 0)
			{
				throw new TlsFatalAlert(50);
			}
			mOfferedCipherSuites = TlsUtilities.ReadUint16Array(num / 2, buf);
			int num2 = TlsUtilities.ReadUint8(buf);
			if (num2 < 1)
			{
				throw new TlsFatalAlert(47);
			}
			mOfferedCompressionMethods = TlsUtilities.ReadUint8Array(num2, buf);
			mClientExtensions = TlsProtocol.ReadExtensions(buf);
			mSecurityParameters.extendedMasterSecret = TlsExtensionsUtilities.HasExtendedMasterSecretExtension(mClientExtensions);
			if (!mSecurityParameters.IsExtendedMasterSecret && mTlsServer.RequiresExtendedMasterSecret())
			{
				throw new TlsFatalAlert(40);
			}
			ContextAdmin.SetClientVersion(protocolVersion);
			mTlsServer.NotifyClientVersion(protocolVersion);
			mTlsServer.NotifyFallback(Arrays.Contains(mOfferedCipherSuites, 22016));
			mSecurityParameters.clientRandom = clientRandom;
			mTlsServer.NotifyOfferedCipherSuites(mOfferedCipherSuites);
			mTlsServer.NotifyOfferedCompressionMethods(mOfferedCompressionMethods);
			if (Arrays.Contains(mOfferedCipherSuites, 255))
			{
				mSecureRenegotiation = true;
			}
			byte[] extensionData = TlsUtilities.GetExtensionData(mClientExtensions, 65281);
			if (extensionData != null)
			{
				mSecureRenegotiation = true;
				if (!Arrays.ConstantTimeAreEqual(extensionData, TlsProtocol.CreateRenegotiationInfo(TlsUtilities.EmptyBytes)))
				{
					throw new TlsFatalAlert(40);
				}
			}
			mTlsServer.NotifySecureRenegotiation(mSecureRenegotiation);
			if (mClientExtensions != null)
			{
				TlsExtensionsUtilities.GetPaddingExtension(mClientExtensions);
				mTlsServer.ProcessClientExtensions(mClientExtensions);
			}
		}

		protected virtual void ReceiveClientKeyExchangeMessage(MemoryStream buf)
		{
			mKeyExchange.ProcessClientKeyExchange(buf);
			TlsProtocol.AssertEmpty(buf);
			if (TlsUtilities.IsSsl(Context))
			{
				TlsProtocol.EstablishMasterSecret(Context, mKeyExchange);
			}
			mPrepareFinishHash = mRecordStream.PrepareToFinish();
			mSecurityParameters.sessionHash = TlsProtocol.GetCurrentPrfHash(Context, mPrepareFinishHash, null);
			if (!TlsUtilities.IsSsl(Context))
			{
				TlsProtocol.EstablishMasterSecret(Context, mKeyExchange);
			}
			mRecordStream.SetPendingConnectionState(Peer.GetCompression(), Peer.GetCipher());
		}

		protected virtual void SendCertificateRequestMessage(CertificateRequest certificateRequest)
		{
			HandshakeMessage handshakeMessage = new HandshakeMessage(13);
			certificateRequest.Encode(handshakeMessage);
			handshakeMessage.WriteToRecordStream(this);
		}

		protected virtual void SendCertificateStatusMessage(CertificateStatus certificateStatus)
		{
			HandshakeMessage handshakeMessage = new HandshakeMessage(22);
			certificateStatus.Encode(handshakeMessage);
			handshakeMessage.WriteToRecordStream(this);
		}

		protected virtual void SendNewSessionTicketMessage(NewSessionTicket newSessionTicket)
		{
			if (newSessionTicket == null)
			{
				throw new TlsFatalAlert(80);
			}
			HandshakeMessage handshakeMessage = new HandshakeMessage(4);
			newSessionTicket.Encode(handshakeMessage);
			handshakeMessage.WriteToRecordStream(this);
		}

		protected virtual void SendServerHelloMessage()
		{
			HandshakeMessage handshakeMessage = new HandshakeMessage(2);
			ProtocolVersion serverVersion = mTlsServer.GetServerVersion();
			if (!serverVersion.IsEqualOrEarlierVersionOf(Context.ClientVersion))
			{
				throw new TlsFatalAlert(80);
			}
			mRecordStream.ReadVersion = serverVersion;
			mRecordStream.SetWriteVersion(serverVersion);
			mRecordStream.SetRestrictReadVersion(enabled: true);
			ContextAdmin.SetServerVersion(serverVersion);
			TlsUtilities.WriteVersion(serverVersion, handshakeMessage);
			handshakeMessage.Write(mSecurityParameters.serverRandom);
			TlsUtilities.WriteOpaque8(TlsUtilities.EmptyBytes, handshakeMessage);
			int selectedCipherSuite = mTlsServer.GetSelectedCipherSuite();
			if (!Arrays.Contains(mOfferedCipherSuites, selectedCipherSuite) || selectedCipherSuite == 0 || CipherSuite.IsScsv(selectedCipherSuite) || !TlsUtilities.IsValidCipherSuiteForVersion(selectedCipherSuite, Context.ServerVersion))
			{
				throw new TlsFatalAlert(80);
			}
			mSecurityParameters.cipherSuite = selectedCipherSuite;
			byte selectedCompressionMethod = mTlsServer.GetSelectedCompressionMethod();
			if (!Arrays.Contains(mOfferedCompressionMethods, selectedCompressionMethod))
			{
				throw new TlsFatalAlert(80);
			}
			mSecurityParameters.compressionAlgorithm = selectedCompressionMethod;
			TlsUtilities.WriteUint16(selectedCipherSuite, handshakeMessage);
			TlsUtilities.WriteUint8(selectedCompressionMethod, handshakeMessage);
			mServerExtensions = TlsExtensionsUtilities.EnsureExtensionsInitialised(mTlsServer.GetServerExtensions());
			if (mSecureRenegotiation)
			{
				byte[] extensionData = TlsUtilities.GetExtensionData(mServerExtensions, 65281);
				if (null == extensionData)
				{
					mServerExtensions[65281] = TlsProtocol.CreateRenegotiationInfo(TlsUtilities.EmptyBytes);
				}
			}
			if (TlsUtilities.IsSsl(mTlsServerContext))
			{
				mSecurityParameters.extendedMasterSecret = false;
			}
			else if (mSecurityParameters.IsExtendedMasterSecret)
			{
				TlsExtensionsUtilities.AddExtendedMasterSecretExtension(mServerExtensions);
			}
			if (mServerExtensions.Count > 0)
			{
				mSecurityParameters.encryptThenMac = TlsExtensionsUtilities.HasEncryptThenMacExtension(mServerExtensions);
				mSecurityParameters.maxFragmentLength = ProcessMaxFragmentLengthExtension(mClientExtensions, mServerExtensions, 80);
				mSecurityParameters.truncatedHMac = TlsExtensionsUtilities.HasTruncatedHMacExtension(mServerExtensions);
				mAllowCertificateStatus = !mResumedSession && TlsUtilities.HasExpectedEmptyExtensionData(mServerExtensions, 5, 80);
				mExpectSessionTicket = !mResumedSession && TlsUtilities.HasExpectedEmptyExtensionData(mServerExtensions, 35, 80);
				TlsProtocol.WriteExtensions(handshakeMessage, mServerExtensions);
			}
			mSecurityParameters.prfAlgorithm = TlsProtocol.GetPrfAlgorithm(Context, mSecurityParameters.CipherSuite);
			mSecurityParameters.verifyDataLength = 12;
			ApplyMaxFragmentLengthExtension();
			handshakeMessage.WriteToRecordStream(this);
		}

		protected virtual void SendServerHelloDoneMessage()
		{
			byte[] array = new byte[4];
			TlsUtilities.WriteUint8(14, array, 0);
			TlsUtilities.WriteUint24(0, array, 1);
			WriteHandshakeMessage(array, 0, array.Length);
		}

		protected virtual void SendServerKeyExchangeMessage(byte[] serverKeyExchange)
		{
			HandshakeMessage handshakeMessage = new HandshakeMessage(12, serverKeyExchange.Length);
			handshakeMessage.Write(serverKeyExchange);
			handshakeMessage.WriteToRecordStream(this);
		}

		protected virtual bool ExpectCertificateVerifyMessage()
		{
			if (mClientCertificateType >= 0)
			{
				return TlsUtilities.HasSigningCapability((byte)mClientCertificateType);
			}
			return false;
		}
	}
	public interface TlsSession
	{
		byte[] SessionID { get; }

		bool IsResumable { get; }

		SessionParameters ExportSessionParameters();

		void Invalidate();
	}
	internal class TlsSessionImpl : TlsSession
	{
		internal readonly byte[] mSessionID;

		internal readonly SessionParameters mSessionParameters;

		internal bool mResumable;

		public virtual byte[] SessionID
		{
			get
			{
				lock (this)
				{
					return mSessionID;
				}
			}
		}

		public virtual bool IsResumable
		{
			get
			{
				lock (this)
				{
					return mResumable;
				}
			}
		}

		internal TlsSessionImpl(byte[] sessionID, SessionParameters sessionParameters)
		{
			if (sessionID == null)
			{
				throw new ArgumentNullException("sessionID");
			}
			if (sessionID.Length > 32)
			{
				throw new ArgumentException("cannot be longer than 32 bytes", "sessionID");
			}
			mSessionID = Arrays.Clone(sessionID);
			mSessionParameters = sessionParameters;
			mResumable = sessionID.Length > 0 && sessionParameters != null && sessionParameters.IsExtendedMasterSecret;
		}

		public virtual SessionParameters ExportSessionParameters()
		{
			lock (this)
			{
				return (mSessionParameters == null) ? null : mSessionParameters.Copy();
			}
		}

		public virtual void Invalidate()
		{
			lock (this)
			{
				mResumable = false;
			}
		}
	}
	public class TlsSrpKeyExchange : AbstractTlsKeyExchange
	{
		protected TlsSigner mTlsSigner;

		protected TlsSrpGroupVerifier mGroupVerifier;

		protected byte[] mIdentity;

		protected byte[] mPassword;

		protected AsymmetricKeyParameter mServerPublicKey = null;

		protected Srp6GroupParameters mSrpGroup = null;

		protected Srp6Client mSrpClient = null;

		protected Srp6Server mSrpServer = null;

		protected BigInteger mSrpPeerCredentials = null;

		protected BigInteger mSrpVerifier = null;

		protected byte[] mSrpSalt = null;

		protected TlsSignerCredentials mServerCredentials = null;

		public override bool RequiresServerKeyExchange => true;

		protected static TlsSigner CreateSigner(int keyExchange)
		{
			return keyExchange switch
			{
				21 => null, 
				23 => new TlsRsaSigner(), 
				22 => new TlsDssSigner(), 
				_ => throw new ArgumentException("unsupported key exchange algorithm"), 
			};
		}

		[Obsolete("Use constructor taking an explicit 'groupVerifier' argument")]
		public TlsSrpKeyExchange(int keyExchange, IList supportedSignatureAlgorithms, byte[] identity, byte[] password)
			: this(keyExchange, supportedSignatureAlgorithms, new DefaultTlsSrpGroupVerifier(), identity, password)
		{
		}

		public TlsSrpKeyExchange(int keyExchange, IList supportedSignatureAlgorithms, TlsSrpGroupVerifier groupVerifier, byte[] identity, byte[] password)
			: base(keyExchange, supportedSignatureAlgorithms)
		{
			mTlsSigner = CreateSigner(keyExchange);
			mGroupVerifier = groupVerifier;
			mIdentity = identity;
			mPassword = password;
			mSrpClient = new Srp6Client();
		}

		public TlsSrpKeyExchange(int keyExchange, IList supportedSignatureAlgorithms, byte[] identity, TlsSrpLoginParameters loginParameters)
			: base(keyExchange, supportedSignatureAlgorithms)
		{
			mTlsSigner = CreateSigner(keyExchange);
			mIdentity = identity;
			mSrpServer = new Srp6Server();
			mSrpGroup = loginParameters.Group;
			mSrpVerifier = loginParameters.Verifier;
			mSrpSalt = loginParameters.Salt;
		}

		public override void Init(TlsContext context)
		{
			base.Init(context);
			if (mTlsSigner != null)
			{
				mTlsSigner.Init(context);
			}
		}

		public override void SkipServerCredentials()
		{
			if (mTlsSigner != null)
			{
				throw new TlsFatalAlert(10);
			}
		}

		public override void ProcessServerCertificate(Certificate serverCertificate)
		{
			if (mTlsSigner == null)
			{
				throw new TlsFatalAlert(10);
			}
			if (serverCertificate.IsEmpty)
			{
				throw new TlsFatalAlert(42);
			}
			X509CertificateStructure certificateAt = serverCertificate.GetCertificateAt(0);
			SubjectPublicKeyInfo subjectPublicKeyInfo = certificateAt.SubjectPublicKeyInfo;
			try
			{
				mServerPublicKey = PublicKeyFactory.CreateKey(subjectPublicKeyInfo);
			}
			catch (Exception alertCause)
			{
				throw new TlsFatalAlert(43, alertCause);
			}
			if (!mTlsSigner.IsValidPublicKey(mServerPublicKey))
			{
				throw new TlsFatalAlert(46);
			}
			TlsUtilities.ValidateKeyUsage(certificateAt, 128);
			base.ProcessServerCertificate(serverCertificate);
		}

		public override void ProcessServerCredentials(TlsCredentials serverCredentials)
		{
			if (mKeyExchange == 21 || !(serverCredentials is TlsSignerCredentials))
			{
				throw new TlsFatalAlert(80);
			}
			ProcessServerCertificate(serverCredentials.Certificate);
			mServerCredentials = (TlsSignerCredentials)serverCredentials;
		}

		public override byte[] GenerateServerKeyExchange()
		{
			mSrpServer.Init(mSrpGroup, mSrpVerifier, TlsUtilities.CreateHash(2), mContext.SecureRandom);
			BigInteger b = mSrpServer.GenerateServerCredentials();
			ServerSrpParams serverSrpParams = new ServerSrpParams(mSrpGroup.N, mSrpGroup.G, mSrpSalt, b);
			DigestInputBuffer digestInputBuffer = new DigestInputBuffer();
			serverSrpParams.Encode(digestInputBuffer);
			if (mServerCredentials != null)
			{
				SignatureAndHashAlgorithm signatureAndHashAlgorithm = TlsUtilities.GetSignatureAndHashAlgorithm(mContext, mServerCredentials);
				IDigest digest = TlsUtilities.CreateHash(signatureAndHashAlgorithm);
				SecurityParameters securityParameters = mContext.SecurityParameters;
				digest.BlockUpdate(securityParameters.clientRandom, 0, securityParameters.clientRandom.Length);
				digest.BlockUpdate(securityParameters.serverRandom, 0, securityParameters.serverRandom.Length);
				digestInputBuffer.UpdateDigest(digest);
				byte[] array = new byte[digest.GetDigestSize()];
				digest.DoFinal(array, 0);
				byte[] signature = mServerCredentials.GenerateCertificateSignature(array);
				DigitallySigned digitallySigned = new DigitallySigned(signatureAndHashAlgorithm, signature);
				digitallySigned.Encode(digestInputBuffer);
			}
			return digestInputBuffer.ToArray();
		}

		public override void ProcessServerKeyExchange(Stream input)
		{
			SecurityParameters securityParameters = mContext.SecurityParameters;
			SignerInputBuffer signerInputBuffer = null;
			Stream input2 = input;
			if (mTlsSigner != null)
			{
				signerInputBuffer = new SignerInputBuffer();
				input2 = new TeeInputStream(input, signerInputBuffer);
			}
			ServerSrpParams serverSrpParams = ServerSrpParams.Parse(input2);
			if (signerInputBuffer != null)
			{
				DigitallySigned digitallySigned = ParseSignature(input);
				ISigner signer = InitVerifyer(mTlsSigner, digitallySigned.Algorithm, securityParameters);
				signerInputBuffer.UpdateSigner(signer);
				if (!signer.VerifySignature(digitallySigned.Signature))
				{
					throw new TlsFatalAlert(51);
				}
			}
			mSrpGroup = new Srp6GroupParameters(serverSrpParams.N, serverSrpParams.G);
			if (!mGroupVerifier.Accept(mSrpGroup))
			{
				throw new TlsFatalAlert(71);
			}
			mSrpSalt = serverSrpParams.S;
			try
			{
				mSrpPeerCredentials = Srp6Utilities.ValidatePublicValue(mSrpGroup.N, serverSrpParams.B);
			}
			catch (CryptoException alertCause)
			{
				throw new TlsFatalAlert(47, alertCause);
			}
			mSrpClient.Init(mSrpGroup, TlsUtilities.CreateHash(2), mContext.SecureRandom);
		}

		public override void ValidateCertificateRequest(CertificateRequest certificateRequest)
		{
			throw new TlsFatalAlert(10);
		}

		public override void ProcessClientCredentials(TlsCredentials clientCredentials)
		{
			throw new TlsFatalAlert(80);
		}

		public override void GenerateClientKeyExchange(Stream output)
		{
			BigInteger x = mSrpClient.GenerateClientCredentials(mSrpSalt, mIdentity, mPassword);
			TlsSrpUtilities.WriteSrpParameter(x, output);
			mContext.SecurityParameters.srpIdentity = Arrays.Clone(mIdentity);
		}

		public override void ProcessClientKeyExchange(Stream input)
		{
			try
			{
				mSrpPeerCredentials = Srp6Utilities.ValidatePublicValue(mSrpGroup.N, TlsSrpUtilities.ReadSrpParameter(input));
			}
			catch (CryptoException alertCause)
			{
				throw new TlsFatalAlert(47, alertCause);
			}
			mContext.SecurityParameters.srpIdentity = Arrays.Clone(mIdentity);
		}

		public override byte[] GeneratePremasterSecret()
		{
			try
			{
				BigInteger n = ((mSrpServer != null) ? mSrpServer.CalculateSecret(mSrpPeerCredentials) : mSrpClient.CalculateSecret(mSrpPeerCredentials));
				return BigIntegers.AsUnsignedByteArray(n);
			}
			catch (CryptoException alertCause)
			{
				throw new TlsFatalAlert(47, alertCause);
			}
		}

		protected virtual ISigner InitVerifyer(TlsSigner tlsSigner, SignatureAndHashAlgorithm algorithm, SecurityParameters securityParameters)
		{
			ISigner signer = tlsSigner.CreateVerifyer(algorithm, mServerPublicKey);
			signer.BlockUpdate(securityParameters.clientRandom, 0, securityParameters.clientRandom.Length);
			signer.BlockUpdate(securityParameters.serverRandom, 0, securityParameters.serverRandom.Length);
			return signer;
		}
	}
	public class TlsSrpLoginParameters
	{
		protected readonly Srp6GroupParameters mGroup;

		protected readonly BigInteger mVerifier;

		protected readonly byte[] mSalt;

		public virtual Srp6GroupParameters Group => mGroup;

		public virtual byte[] Salt => mSalt;

		public virtual BigInteger Verifier => mVerifier;

		public TlsSrpLoginParameters(Srp6GroupParameters group, BigInteger verifier, byte[] salt)
		{
			mGroup = group;
			mVerifier = verifier;
			mSalt = salt;
		}
	}
	public abstract class TlsSrpUtilities
	{
		public static void AddSrpExtension(IDictionary extensions, byte[] identity)
		{
			extensions[12] = CreateSrpExtension(identity);
		}

		public static byte[] GetSrpExtension(IDictionary extensions)
		{
			byte[] extensionData = TlsUtilities.GetExtensionData(extensions, 12);
			if (extensionData != null)
			{
				return ReadSrpExtension(extensionData);
			}
			return null;
		}

		public static byte[] CreateSrpExtension(byte[] identity)
		{
			if (identity == null)
			{
				throw new TlsFatalAlert(80);
			}
			return TlsUtilities.EncodeOpaque8(identity);
		}

		public static byte[] ReadSrpExtension(byte[] extensionData)
		{
			if (extensionData == null)
			{
				throw new ArgumentNullException("extensionData");
			}
			MemoryStream memoryStream = new MemoryStream(extensionData, writable: false);
			byte[] result = TlsUtilities.ReadOpaque8(memoryStream);
			TlsProtocol.AssertEmpty(memoryStream);
			return result;
		}

		public static BigInteger ReadSrpParameter(Stream input)
		{
			return new BigInteger(1, TlsUtilities.ReadOpaque16(input));
		}

		public static void WriteSrpParameter(BigInteger x, Stream output)
		{
			TlsUtilities.WriteOpaque16(BigIntegers.AsUnsignedByteArray(x), output);
		}

		public static bool IsSrpCipherSuite(int cipherSuite)
		{
			switch (cipherSuite)
			{
			case 49178:
			case 49179:
			case 49180:
			case 49181:
			case 49182:
			case 49183:
			case 49184:
			case 49185:
			case 49186:
				return true;
			default:
				return false;
			}
		}
	}
	public abstract class TlsSRTPUtils
	{
		public static void AddUseSrtpExtension(IDictionary extensions, UseSrtpData useSRTPData)
		{
			extensions[14] = CreateUseSrtpExtension(useSRTPData);
		}

		public static UseSrtpData GetUseSrtpExtension(IDictionary extensions)
		{
			byte[] extensionData = TlsUtilities.GetExtensionData(extensions, 14);
			if (extensionData != null)
			{
				return ReadUseSrtpExtension(extensionData);
			}
			return null;
		}

		public static byte[] CreateUseSrtpExtension(UseSrtpData useSrtpData)
		{
			if (useSrtpData == null)
			{
				throw new ArgumentNullException("useSrtpData");
			}
			MemoryStream memoryStream = new MemoryStream();
			TlsUtilities.WriteUint16ArrayWithUint16Length(useSrtpData.ProtectionProfiles, memoryStream);
			TlsUtilities.WriteOpaque8(useSrtpData.Mki, memoryStream);
			return memoryStream.ToArray();
		}

		public static UseSrtpData ReadUseSrtpExtension(byte[] extensionData)
		{
			if (extensionData == null)
			{
				throw new ArgumentNullException("extensionData");
			}
			MemoryStream memoryStream = new MemoryStream(extensionData, writable: true);
			int num = TlsUtilities.ReadUint16(memoryStream);
			if (num < 2 || ((uint)num & (true ? 1u : 0u)) != 0)
			{
				throw new TlsFatalAlert(50);
			}
			int[] protectionProfiles = TlsUtilities.ReadUint16Array(num / 2, memoryStream);
			byte[] mki = TlsUtilities.ReadOpaque8(memoryStream);
			TlsProtocol.AssertEmpty(memoryStream);
			return new UseSrtpData(protectionProfiles, mki);
		}
	}
	internal class TlsStream : Stream
	{
		private readonly TlsProtocol handler;

		public override bool CanRead => !handler.IsClosed;

		public override bool CanSeek => false;

		public override bool CanWrite => !handler.IsClosed;

		public override long Length
		{
			get
			{
				throw new NotSupportedException();
			}
		}

		public override long Position
		{
			get
			{
				throw new NotSupportedException();
			}
