			z[0] = (uint)num;
			num >>= 32;
			if (num != 0)
			{
				num = Nat.IncAt(7, z, 1);
			}
			num += (long)z[7] - 2147483648L;
			z[7] = (uint)num;
			num >>= 32;
			return (int)num;
		}

		private static int SubPExtFrom(uint[] zz)
		{
			long num = (long)zz[0] - (long)PExt[0];
			zz[0] = (uint)num;
			num >>= 32;
