			uint[] z = Nat256.Create();
			Mod.Invert(Curve25519Field.P, x, z);
			return new Curve25519FieldElement(z);
		}

		public override ECFieldElement Sqrt()
		{
			uint[] y = x;
			if (Nat256.IsZero(y) || Nat256.IsOne(y))
			{
				return this;
			}
			uint[] array = Nat256.Create();
			Curve25519Field.Square(y, array);
			Curve25519Field.Multiply(array, y, array);
			uint[] array2 = array;
			Curve25519Field.Square(array, array2);
			Curve25519Field.Multiply(array2, y, array2);
			uint[] array3 = Nat256.Create();
			Curve25519Field.Square(array2, array3);
			Curve25519Field.Multiply(array3, y, array3);
			uint[] array4 = Nat256.Create();
			Curve25519Field.SquareN(array3, 3, array4);
			Curve25519Field.Multiply(array4, array2, array4);
			uint[] array5 = array2;
			Curve25519Field.SquareN(array4, 4, array5);
			Curve25519Field.Multiply(array5, array3, array5);
			uint[] array6 = array4;
			Curve25519Field.SquareN(array5, 4, array6);
			Curve25519Field.Multiply(array6, array3, array6);
			uint[] array7 = array3;
			Curve25519Field.SquareN(array6, 15, array7);
			Curve25519Field.Multiply(array7, array6, array7);
			uint[] array8 = array6;
			Curve25519Field.SquareN(array7, 30, array8);
			Curve25519Field.Multiply(array8, array7, array8);
			uint[] array9 = array7;
			Curve25519Field.SquareN(array8, 60, array9);
			Curve25519Field.Multiply(array9, array8, array9);
			uint[] z = array8;
			Curve25519Field.SquareN(array9, 11, z);
			Curve25519Field.Multiply(z, array5, z);
			uint[] array10 = array5;
			Curve25519Field.SquareN(z, 120, array10);
			Curve25519Field.Multiply(array10, array9, array10);
			uint[] z2 = array10;
			Curve25519Field.Square(z2, z2);
			uint[] array11 = array9;
			Curve25519Field.Square(z2, array11);
			if (Nat256.Eq(y, array11))
			{
				return new Curve25519FieldElement(z2);
			}
			Curve25519Field.Multiply(z2, PRECOMP_POW2, z2);
			Curve25519Field.Square(z2, array11);
			if (Nat256.Eq(y, array11))
			{
				return new Curve25519FieldElement(z2);
			}
			return null;
		}

		public override bool Equals(object obj)
		{
			return Equals(obj as Curve25519FieldElement);
		}

		public override bool Equals(ECFieldElement other)
		{
			return Equals(other as Curve25519FieldElement);
		}

		public virtual bool Equals(Curve25519FieldElement other)
		{
			if (this == other)
			{
				return true;
			}
			if (other == null)
			{
				return false;
			}
			return Nat256.Eq(x, other.x);
		}

		public override int GetHashCode()
		{
			return Q.GetHashCode() ^ Arrays.GetHashCode(x, 0, 8);
		}
	}
}
namespace Org.BouncyCastle.Math.EC
{
	public abstract class ECPoint
	{
		private class ValidityCallback : IPreCompCallback
		{
			private readonly ECPoint m_outer;

			private readonly bool m_decompressed;

			private readonly bool m_checkOrder;

			internal ValidityCallback(ECPoint outer, bool decompressed, bool checkOrder)
			{
				m_outer = outer;
				m_decompressed = decompressed;
				m_checkOrder = checkOrder;
			}

			public PreCompInfo Precompute(PreCompInfo existing)
			{
				ValidityPreCompInfo validityPreCompInfo = existing as ValidityPreCompInfo;
				if (validityPreCompInfo == null)
				{
					validityPreCompInfo = new ValidityPreCompInfo();
				}
				if (validityPreCompInfo.HasFailed())
				{
					return validityPreCompInfo;
				}
				if (!validityPreCompInfo.HasCurveEquationPassed())
				{
					if (!m_decompressed && !m_outer.SatisfiesCurveEquation())
					{
						validityPreCompInfo.ReportFailed();
						return validityPreCompInfo;
					}
					validityPreCompInfo.ReportCurveEquationPassed();
				}
				if (m_checkOrder && !validityPreCompInfo.HasOrderPassed())
				{
					if (!m_outer.SatisfiesOrder())
					{
						validityPreCompInfo.ReportFailed();
						return validityPreCompInfo;
					}
					validityPreCompInfo.ReportOrderPassed();
				}
				return validityPreCompInfo;
			}
		}

		protected static ECFieldElement[] EMPTY_ZS = new ECFieldElement[0];

		protected internal readonly ECCurve m_curve;

		protected internal readonly ECFieldElement m_x;

		protected internal readonly ECFieldElement m_y;

		protected internal readonly ECFieldElement[] m_zs;

		protected internal readonly bool m_withCompression;

		protected internal IDictionary m_preCompTable = null;

		public virtual ECCurve Curve => m_curve;

		protected virtual int CurveCoordinateSystem
		{
			get
			{
				if (m_curve != null)
				{
					return m_curve.CoordinateSystem;
				}
				return 0;
			}
		}

		public virtual ECFieldElement AffineXCoord
		{
			get
			{
				CheckNormalized();
				return XCoord;
			}
		}

		public virtual ECFieldElement AffineYCoord
		{
			get
			{
				CheckNormalized();
				return YCoord;
			}
		}

		public virtual ECFieldElement XCoord => m_x;

		public virtual ECFieldElement YCoord => m_y;

		protected internal ECFieldElement RawXCoord => m_x;

		protected internal ECFieldElement RawYCoord => m_y;

		protected internal ECFieldElement[] RawZCoords => m_zs;

		public bool IsInfinity
		{
			get
			{
				if (m_x == null)
				{
					return m_y == null;
				}
				return false;
			}
		}

		public bool IsCompressed => m_withCompression;

		protected internal abstract bool CompressionYTilde { get; }

		protected static ECFieldElement[] GetInitialZCoords(ECCurve curve)
		{
			int num = curve?.CoordinateSystem ?? 0;
			int num2 = num;
			if (num2 == 0 || num2 == 5)
			{
				return EMPTY_ZS;
			}
			ECFieldElement eCFieldElement = curve.FromBigInteger(BigInteger.One);
			switch (num)
			{
			case 1:
			case 2:
			case 6:
				return new ECFieldElement[1] { eCFieldElement };
			case 3:
				return new ECFieldElement[3] { eCFieldElement, eCFieldElement, eCFieldElement };
			case 4:
				return new ECFieldElement[2] { eCFieldElement, curve.A };
			default:
				throw new ArgumentException("unknown coordinate system");
			}
		}

		protected ECPoint(ECCurve curve, ECFieldElement x, ECFieldElement y, bool withCompression)
			: this(curve, x, y, GetInitialZCoords(curve), withCompression)
		{
		}

		internal ECPoint(ECCurve curve, ECFieldElement x, ECFieldElement y, ECFieldElement[] zs, bool withCompression)
		{
			m_curve = curve;
			m_x = x;
			m_y = y;
			m_zs = zs;
			m_withCompression = withCompression;
		}

		protected abstract bool SatisfiesCurveEquation();

		protected virtual bool SatisfiesOrder()
		{
			if (BigInteger.One.Equals(Curve.Cofactor))
			{
				return true;
			}
			BigInteger order = Curve.Order;
			if (order != null)
			{
				return ECAlgorithms.ReferenceMultiply(this, order).IsInfinity;
			}
			return true;
		}

		public ECPoint GetDetachedPoint()
		{
			return Normalize().Detach();
		}

		protected abstract ECPoint Detach();

		public virtual ECFieldElement GetZCoord(int index)
		{
			if (index >= 0 && index < m_zs.Length)
			{
				return m_zs[index];
			}
			return null;
		}

		public virtual ECFieldElement[] GetZCoords()
		{
			int num = m_zs.Length;
			if (num == 0)
			{
				return m_zs;
			}
			ECFieldElement[] array = new ECFieldElement[num];
			Array.Copy(m_zs, 0, array, 0, num);
			return array;
		}

		protected virtual void CheckNormalized()
		{
			if (!IsNormalized())
			{
				throw new InvalidOperationException("point not in normal form");
			}
		}

		public virtual bool IsNormalized()
		{
			int curveCoordinateSystem = CurveCoordinateSystem;
			if (curveCoordinateSystem != 0 && curveCoordinateSystem != 5 && !IsInfinity)
			{
				return RawZCoords[0].IsOne;
			}
			return true;
		}

		public virtual ECPoint Normalize()
		{
			if (IsInfinity)
			{
				return this;
			}
			int curveCoordinateSystem = CurveCoordinateSystem;
			if (curveCoordinateSystem == 0 || curveCoordinateSystem == 5)
			{
				return this;
			}
			ECFieldElement eCFieldElement = RawZCoords[0];
			if (eCFieldElement.IsOne)
			{
				return this;
			}
			return Normalize(eCFieldElement.Invert());
		}

		internal virtual ECPoint Normalize(ECFieldElement zInv)
		{
			switch (CurveCoordinateSystem)
			{
			case 1:
			case 6:
				return CreateScaledPoint(zInv, zInv);
			case 2:
			case 3:
			case 4:
			{
				ECFieldElement eCFieldElement = zInv.Square();
				ECFieldElement sy = eCFieldElement.Multiply(zInv);
				return CreateScaledPoint(eCFieldElement, sy);
			}
			default:
				throw new InvalidOperationException("not a projective coordinate system");
			}
		}

		protected virtual ECPoint CreateScaledPoint(ECFieldElement sx, ECFieldElement sy)
		{
			return Curve.CreateRawPoint(RawXCoord.Multiply(sx), RawYCoord.Multiply(sy), IsCompressed);
		}

		public bool IsValid()
		{
			return ImplIsValid(decompressed: false, checkOrder: true);
		}

		internal bool IsValidPartial()
		{
			return ImplIsValid(decompressed: false, checkOrder: false);
		}

		internal bool ImplIsValid(bool decompressed, bool checkOrder)
		{
			if (IsInfinity)
			{
				return true;
			}
			ValidityCallback callback = new ValidityCallback(this, decompressed, checkOrder);
			ValidityPreCompInfo validityPreCompInfo = (ValidityPreCompInfo)Curve.Precompute(this, ValidityPreCompInfo.PRECOMP_NAME, callback);
			return !validityPreCompInfo.HasFailed();
		}

		public virtual ECPoint ScaleX(ECFieldElement scale)
		{
			if (!IsInfinity)
			{
				return Curve.CreateRawPoint(RawXCoord.Multiply(scale), RawYCoord, RawZCoords, IsCompressed);
			}
			return this;
		}

		public virtual ECPoint ScaleXNegateY(ECFieldElement scale)
		{
			if (!IsInfinity)
			{
				return Curve.CreateRawPoint(RawXCoord.Multiply(scale), RawYCoord.Negate(), RawZCoords, IsCompressed);
			}
			return this;
		}

		public virtual ECPoint ScaleY(ECFieldElement scale)
		{
			if (!IsInfinity)
			{
				return Curve.CreateRawPoint(RawXCoord, RawYCoord.Multiply(scale), RawZCoords, IsCompressed);
			}
			return this;
		}

		public virtual ECPoint ScaleYNegateX(ECFieldElement scale)
		{
			if (!IsInfinity)
			{
				return Curve.CreateRawPoint(RawXCoord.Negate(), RawYCoord.Multiply(scale), RawZCoords, IsCompressed);
			}
			return this;
		}

		public override bool Equals(object obj)
		{
			return Equals(obj as ECPoint);
		}

		public virtual bool Equals(ECPoint other)
		{
			if (this == other)
			{
				return true;
			}
			if (other == null)
			{
				return false;
			}
			ECCurve curve = Curve;
			ECCurve curve2 = other.Curve;
			bool flag = null == curve;
			bool flag2 = null == curve2;
			bool isInfinity = IsInfinity;
			bool isInfinity2 = other.IsInfinity;
			if (isInfinity || isInfinity2)
			{
				if (isInfinity && isInfinity2)
				{
					if (!flag && !flag2)
					{
						return curve.Equals(curve2);
					}
					return true;
				}
				return false;
			}
			ECPoint eCPoint = this;
			ECPoint eCPoint2 = other;
			if (!flag || !flag2)
			{
				if (flag)
				{
					eCPoint2 = eCPoint2.Normalize();
				}
				else if (flag2)
				{
					eCPoint = eCPoint.Normalize();
				}
				else
				{
					if (!curve.Equals(curve2))
					{
						return false;
					}
					ECPoint[] array = new ECPoint[2]
					{
						this,
						curve.ImportPoint(eCPoint2)
					};
					curve.NormalizeAll(array);
					eCPoint = array[0];
					eCPoint2 = array[1];
				}
			}
			if (eCPoint.XCoord.Equals(eCPoint2.XCoord))
			{
				return eCPoint.YCoord.Equals(eCPoint2.YCoord);
			}
			return false;
		}

		public override int GetHashCode()
		{
			ECCurve curve = Curve;
			int num = ((curve != null) ? (~curve.GetHashCode()) : 0);
			if (!IsInfinity)
			{
				ECPoint eCPoint = Normalize();
				num ^= eCPoint.XCoord.GetHashCode() * 17;
				num ^= eCPoint.YCoord.GetHashCode() * 257;
			}
			return num;
		}

		public override string ToString()
		{
			if (IsInfinity)
			{
				return "INF";
			}
			StringBuilder stringBuilder = new StringBuilder();
			stringBuilder.Append('(');
			stringBuilder.Append(RawXCoord);
			stringBuilder.Append(',');
			stringBuilder.Append(RawYCoord);
			for (int i = 0; i < m_zs.Length; i++)
			{
				stringBuilder.Append(',');
				stringBuilder.Append(m_zs[i]);
			}
			stringBuilder.Append(')');
			return stringBuilder.ToString();
		}

		public virtual byte[] GetEncoded()
		{
			return GetEncoded(m_withCompression);
		}

		public abstract byte[] GetEncoded(bool compressed);

		public abstract ECPoint Add(ECPoint b);

		public abstract ECPoint Subtract(ECPoint b);

		public abstract ECPoint Negate();

		public virtual ECPoint TimesPow2(int e)
		{
			if (e < 0)
			{
				throw new ArgumentException("cannot be negative", "e");
			}
			ECPoint eCPoint = this;
			while (--e >= 0)
			{
				eCPoint = eCPoint.Twice();
			}
			return eCPoint;
		}

		public abstract ECPoint Twice();

		public abstract ECPoint Multiply(BigInteger b);

		public virtual ECPoint TwicePlus(ECPoint b)
		{
			return Twice().Add(b);
		}

		public virtual ECPoint ThreeTimes()
		{
			return TwicePlus(this);
		}
	}
}
namespace Org.BouncyCastle.Math.EC.Multiplier
{
	public interface IPreCompCallback
	{
		PreCompInfo Precompute(PreCompInfo existing);
	}
}
namespace Org.BouncyCastle.Math.EC
{
	public abstract class ECPointBase : ECPoint
	{
		protected internal ECPointBase(ECCurve curve, ECFieldElement x, ECFieldElement y, bool withCompression)
			: base(curve, x, y, withCompression)
		{
		}

		protected internal ECPointBase(ECCurve curve, ECFieldElement x, ECFieldElement y, ECFieldElement[] zs, bool withCompression)
			: base(curve, x, y, zs, withCompression)
		{
		}

		public override byte[] GetEncoded(bool compressed)
		{
			if (base.IsInfinity)
			{
				return new byte[1];
			}
			ECPoint eCPoint = Normalize();
			byte[] encoded = eCPoint.XCoord.GetEncoded();
			if (compressed)
			{
				byte[] array = new byte[encoded.Length + 1];
				array[0] = (byte)(eCPoint.CompressionYTilde ? 3u : 2u);
				Array.Copy(encoded, 0, array, 1, encoded.Length);
				return array;
			}
			byte[] encoded2 = eCPoint.YCoord.GetEncoded();
			byte[] array2 = new byte[encoded.Length + encoded2.Length + 1];
			array2[0] = 4;
			Array.Copy(encoded, 0, array2, 1, encoded.Length);
			Array.Copy(encoded2, 0, array2, encoded.Length + 1, encoded2.Length);
			return array2;
		}

		public override ECPoint Multiply(BigInteger k)
		{
			return Curve.GetMultiplier().Multiply(this, k);
		}
	}
	public abstract class AbstractFpPoint : ECPointBase
	{
		protected internal override bool CompressionYTilde => AffineYCoord.TestBitZero();

		protected AbstractFpPoint(ECCurve curve, ECFieldElement x, ECFieldElement y, bool withCompression)
			: base(curve, x, y, withCompression)
		{
		}

		protected AbstractFpPoint(ECCurve curve, ECFieldElement x, ECFieldElement y, ECFieldElement[] zs, bool withCompression)
			: base(curve, x, y, zs, withCompression)
		{
		}

		protected override bool SatisfiesCurveEquation()
		{
			ECFieldElement rawXCoord = base.RawXCoord;
			ECFieldElement rawYCoord = base.RawYCoord;
			ECFieldElement eCFieldElement = Curve.A;
			ECFieldElement eCFieldElement2 = Curve.B;
			ECFieldElement eCFieldElement3 = rawYCoord.Square();
			switch (CurveCoordinateSystem)
			{
			case 1:
			{
				ECFieldElement eCFieldElement6 = base.RawZCoords[0];
				if (!eCFieldElement6.IsOne)
				{
					ECFieldElement b3 = eCFieldElement6.Square();
					ECFieldElement b4 = eCFieldElement6.Multiply(b3);
					eCFieldElement3 = eCFieldElement3.Multiply(eCFieldElement6);
					eCFieldElement = eCFieldElement.Multiply(b3);
					eCFieldElement2 = eCFieldElement2.Multiply(b4);
				}
				break;
			}
			case 2:
			case 3:
			case 4:
			{
				ECFieldElement eCFieldElement4 = base.RawZCoords[0];
				if (!eCFieldElement4.IsOne)
				{
					ECFieldElement eCFieldElement5 = eCFieldElement4.Square();
					ECFieldElement b = eCFieldElement5.Square();
					ECFieldElement b2 = eCFieldElement5.Multiply(b);
					eCFieldElement = eCFieldElement.Multiply(b);
					eCFieldElement2 = eCFieldElement2.Multiply(b2);
				}
				break;
			}
			default:
				throw new InvalidOperationException("unsupported coordinate system");
			case 0:
				break;
			}
			ECFieldElement other = rawXCoord.Square().Add(eCFieldElement).Multiply(rawXCoord)
				.Add(eCFieldElement2);
			return eCFieldElement3.Equals(other);
		}

		public override ECPoint Subtract(ECPoint b)
		{
			if (b.IsInfinity)
			{
				return this;
			}
			return Add(b.Negate());
		}
	}
}
namespace Org.BouncyCastle.Math.EC.Custom.Djb
{
	internal class Curve25519Point : AbstractFpPoint
	{
		public Curve25519Point(ECCurve curve, ECFieldElement x, ECFieldElement y)
			: this(curve, x, y, withCompression: false)
		{
		}

		public Curve25519Point(ECCurve curve, ECFieldElement x, ECFieldElement y, bool withCompression)
			: base(curve, x, y, withCompression)
		{
			if (x == null != (y == null))
			{
				throw new ArgumentException("Exactly one of the field elements is null");
			}
		}

		internal Curve25519Point(ECCurve curve, ECFieldElement x, ECFieldElement y, ECFieldElement[] zs, bool withCompression)
			: base(curve, x, y, zs, withCompression)
		{
		}

		protected override ECPoint Detach()
		{
			return new Curve25519Point(null, AffineXCoord, AffineYCoord);
		}

		public override ECFieldElement GetZCoord(int index)
		{
			if (index == 1)
			{
				return GetJacobianModifiedW();
			}
			return base.GetZCoord(index);
		}

		public override ECPoint Add(ECPoint b)
		{
			if (base.IsInfinity)
			{
				return b;
			}
			if (b.IsInfinity)
			{
				return this;
			}
			if (this == b)
			{
				return Twice();
			}
			ECCurve curve = Curve;
			Curve25519FieldElement curve25519FieldElement = (Curve25519FieldElement)base.RawXCoord;
			Curve25519FieldElement curve25519FieldElement2 = (Curve25519FieldElement)base.RawYCoord;
			Curve25519FieldElement curve25519FieldElement3 = (Curve25519FieldElement)base.RawZCoords[0];
			Curve25519FieldElement curve25519FieldElement4 = (Curve25519FieldElement)b.RawXCoord;
			Curve25519FieldElement curve25519FieldElement5 = (Curve25519FieldElement)b.RawYCoord;
			Curve25519FieldElement curve25519FieldElement6 = (Curve25519FieldElement)b.RawZCoords[0];
			uint[] array = Nat256.CreateExt();
			uint[] array2 = Nat256.Create();
			uint[] array3 = Nat256.Create();
			uint[] array4 = Nat256.Create();
			bool isOne = curve25519FieldElement3.IsOne;
			uint[] array5;
			uint[] array6;
			if (isOne)
			{
				array5 = curve25519FieldElement4.x;
				array6 = curve25519FieldElement5.x;
			}
			else
			{
				array6 = array3;
				Curve25519Field.Square(curve25519FieldElement3.x, array6);
				array5 = array2;
				Curve25519Field.Multiply(array6, curve25519FieldElement4.x, array5);
				Curve25519Field.Multiply(array6, curve25519FieldElement3.x, array6);
				Curve25519Field.Multiply(array6, curve25519FieldElement5.x, array6);
			}
			bool isOne2 = curve25519FieldElement6.IsOne;
			uint[] array7;
			uint[] array8;
			if (isOne2)
			{
				array7 = curve25519FieldElement.x;
				array8 = curve25519FieldElement2.x;
			}
			else
			{
				array8 = array4;
				Curve25519Field.Square(curve25519FieldElement6.x, array8);
				array7 = array;
				Curve25519Field.Multiply(array8, curve25519FieldElement.x, array7);
				Curve25519Field.Multiply(array8, curve25519FieldElement6.x, array8);
				Curve25519Field.Multiply(array8, curve25519FieldElement2.x, array8);
			}
			uint[] array9 = Nat256.Create();
			Curve25519Field.Subtract(array7, array5, array9);
			uint[] array10 = array2;
			Curve25519Field.Subtract(array8, array6, array10);
			if (Nat256.IsZero(array9))
			{
				if (Nat256.IsZero(array10))
				{
					return Twice();
				}
				return curve.Infinity;
			}
			uint[] array11 = Nat256.Create();
			Curve25519Field.Square(array9, array11);
			uint[] array12 = Nat256.Create();
			Curve25519Field.Multiply(array11, array9, array12);
			uint[] array13 = array3;
			Curve25519Field.Multiply(array11, array7, array13);
			Curve25519Field.Negate(array12, array12);
