				Nat256.Copy(((SM2P256V1FieldElement)eCPoint.RawXCoord).x, 0, array, num);
				num += 8;
				Nat256.Copy(((SM2P256V1FieldElement)eCPoint.RawYCoord).x, 0, array, num);
				num += 8;
			}
			return new SM2P256V1LookupTable(this, array, len);
		}
