			SM2P256V1FieldElement sM2P256V1FieldElement2 = (SM2P256V1FieldElement)base.RawXCoord;
			SM2P256V1FieldElement sM2P256V1FieldElement3 = (SM2P256V1FieldElement)base.RawZCoords[0];
