						uint[] array4 = (array3 = array);
						int num3 = j;
						nint num4 = num3;
						array4[num3] = array3[num4] ^ (m_table[num + j] & num2);
						uint[] array5 = (array3 = array2);
						int num5 = j;
						num4 = num5;
						array5[num5] = array3[num4] ^ (m_table[num + 8 + j] & num2);
					}
					num += 16;
