		public static void Square(ulong[] x, ulong[] z)
		{
			ulong[] array = Nat128.CreateExt64();
			ImplSquare(x, array);
			Reduce(array, z);
		}

		public static void SquareAddToExt(ulong[] x, ulong[] zz)
		{
			ulong[] array = Nat128.CreateExt64();
			ImplSquare(x, array);
			AddExt(zz, array, zz);
		}

		public static void SquareN(ulong[] x, int n, ulong[] z)
		{
			ulong[] array = Nat128.CreateExt64();
			ImplSquare(x, array);
			Reduce(array, z);
			while (--n > 0)
			{
				ImplSquare(z, array);
				Reduce(array, z);
			}
		}

		public static uint Trace(ulong[] x)
		{
			return (uint)(int)x[0] & 1u;
		}

		protected static void ImplMultiply(ulong[] x, ulong[] y, ulong[] zz)
		{
			ulong num = x[0];
			ulong num2 = x[1];
			num2 = ((num >> 57) ^ (num2 << 7)) & 0x1FFFFFFFFFFFFFFuL;
			num &= 0x1FFFFFFFFFFFFFFuL;
			ulong num3 = y[0];
			ulong num4 = y[1];
			num4 = ((num3 >> 57) ^ (num4 << 7)) & 0x1FFFFFFFFFFFFFFuL;
			num3 &= 0x1FFFFFFFFFFFFFFuL;
			ulong[] array = new ulong[6];
			ImplMulw(num, num3, array, 0);
			ImplMulw(num2, num4, array, 2);
			ImplMulw(num ^ num2, num3 ^ num4, array, 4);
			ulong num5 = array[1] ^ array[2];
			ulong num6 = array[0];
			ulong num7 = array[3];
			ulong num8 = array[4] ^ num6 ^ num5;
			ulong num9 = array[5] ^ num7 ^ num5;
			zz[0] = num6 ^ (num8 << 57);
			zz[1] = (num8 >> 7) ^ (num9 << 50);
			zz[2] = (num9 >> 14) ^ (num7 << 43);
			zz[3] = num7 >> 21;
		}

		protected static void ImplMulw(ulong x, ulong y, ulong[] z, int zOff)
		{
			ulong[] array = new ulong[8];
			array[1] = y;
			array[2] = array[1] << 1;
			array[3] = array[2] ^ y;
			array[4] = array[2] << 1;
			array[5] = array[4] ^ y;
			array[6] = array[3] << 1;
			array[7] = array[6] ^ y;
			uint num = (uint)x;
			ulong num2 = 0uL;
			ulong num3 = array[num & 7];
			int num4 = 48;
			do
			{
				num = (uint)(x >> num4);
				ulong num5 = array[num & 7] ^ (array[(num >> 3) & 7] << 3) ^ (array[(num >> 6) & 7] << 6);
				num3 ^= num5 << num4;
				num2 ^= num5 >> -num4;
			}
			while ((num4 -= 9) > 0);
			num2 ^= (x & 0x100804020100800L & (ulong)((long)(y << 7) >> 63)) >> 8;
			z[zOff] = num3 & 0x1FFFFFFFFFFFFFFuL;
			z[zOff + 1] = (num3 >> 57) ^ (num2 << 7);
		}

		protected static void ImplSquare(ulong[] x, ulong[] zz)
		{
			Interleave.Expand64To128(x[0], zz, 0);
			Interleave.Expand64To128(x[1], zz, 2);
		}
	}
