namespace Org.BouncyCastle.Math.EC
{
	public abstract class AbstractF2mCurve : ECCurve
	{
		private BigInteger[] si = null;

		public virtual bool IsKoblitz
		{
			get
			{
				if (m_order != null && m_cofactor != null && m_b.IsOne)
				{
					if (!m_a.IsZero)
					{
						return m_a.IsOne;
					}
					return true;
				}
				return false;
			}
		}

		public static BigInteger Inverse(int m, int[] ks, BigInteger x)
		{
			return new LongArray(x).ModInverse(m, ks).ToBigInteger();
		}

		private static IFiniteField BuildField(int m, int k1, int k2, int k3)
		{
			if (k1 == 0)
			{
				throw new ArgumentException("k1 must be > 0");
			}
			if (k2 == 0)
			{
				if (k3 != 0)
				{
					throw new ArgumentException("k3 must be 0 if k2 == 0");
				}
				return FiniteFields.GetBinaryExtensionField(new int[3] { 0, k1, m });
			}
			if (k2 <= k1)
			{
				throw new ArgumentException("k2 must be > k1");
			}
			if (k3 <= k2)
			{
				throw new ArgumentException("k3 must be > k2");
			}
			return FiniteFields.GetBinaryExtensionField(new int[5] { 0, k1, k2, k3, m });
		}

		protected AbstractF2mCurve(int m, int k1, int k2, int k3)
			: base(BuildField(m, k1, k2, k3))
		{
		}

		public override bool IsValidFieldElement(BigInteger x)
		{
			if (x != null && x.SignValue >= 0)
			{
				return x.BitLength <= FieldSize;
			}
			return false;
		}

		[Obsolete("Per-point compression property will be removed")]
		public override ECPoint CreatePoint(BigInteger x, BigInteger y, bool withCompression)
		{
			ECFieldElement eCFieldElement = FromBigInteger(x);
			ECFieldElement eCFieldElement2 = FromBigInteger(y);
			switch (CoordinateSystem)
			{
			case 5:
			case 6:
				if (eCFieldElement.IsZero)
				{
					if (!eCFieldElement2.Square().Equals(B))
					{
						throw new ArgumentException();
					}
				}
				else
				{
					eCFieldElement2 = eCFieldElement2.Divide(eCFieldElement).Add(eCFieldElement);
				}
				break;
			}
			return CreateRawPoint(eCFieldElement, eCFieldElement2, withCompression);
		}

		protected override ECPoint DecompressPoint(int yTilde, BigInteger X1)
		{
			ECFieldElement eCFieldElement = FromBigInteger(X1);
			ECFieldElement eCFieldElement2 = null;
			if (eCFieldElement.IsZero)
			{
				eCFieldElement2 = B.Sqrt();
			}
			else
			{
				ECFieldElement beta = eCFieldElement.Square().Invert().Multiply(B)
					.Add(A)
					.Add(eCFieldElement);
				ECFieldElement eCFieldElement3 = SolveQuadraticEquation(beta);
				if (eCFieldElement3 != null)
				{
					if (eCFieldElement3.TestBitZero() != (yTilde == 1))
					{
						eCFieldElement3 = eCFieldElement3.AddOne();
					}
					switch (CoordinateSystem)
					{
					case 5:
					case 6:
						eCFieldElement2 = eCFieldElement3.Add(eCFieldElement);
						break;
					default:
						eCFieldElement2 = eCFieldElement3.Multiply(eCFieldElement);
						break;
					}
				}
			}
			if (eCFieldElement2 == null)
			{
				throw new ArgumentException("Invalid point compression");
			}
			return CreateRawPoint(eCFieldElement, eCFieldElement2, withCompression: true);
		}

		internal ECFieldElement SolveQuadraticEquation(ECFieldElement beta)
		{
			AbstractF2mFieldElement abstractF2mFieldElement = (AbstractF2mFieldElement)beta;
			bool hasFastTrace = abstractF2mFieldElement.HasFastTrace;
			if (hasFastTrace && abstractF2mFieldElement.Trace() != 0)
			{
				return null;
			}
			int fieldSize = FieldSize;
			if (((uint)fieldSize & (true ? 1u : 0u)) != 0)
			{
				ECFieldElement eCFieldElement = abstractF2mFieldElement.HalfTrace();
				if (hasFastTrace || eCFieldElement.Square().Add(eCFieldElement).Add(beta)
					.IsZero)
				{
					return eCFieldElement;
				}
				return null;
			}
			if (beta.IsZero)
			{
				return beta;
			}
			ECFieldElement eCFieldElement2 = FromBigInteger(BigInteger.Zero);
			ECFieldElement eCFieldElement3;
			ECFieldElement eCFieldElement6;
			do
			{
				ECFieldElement b = FromBigInteger(BigInteger.Arbitrary(fieldSize));
				eCFieldElement3 = eCFieldElement2;
				ECFieldElement eCFieldElement4 = beta;
				for (int i = 1; i < fieldSize; i++)
				{
					ECFieldElement eCFieldElement5 = eCFieldElement4.Square();
					eCFieldElement3 = eCFieldElement3.Square().Add(eCFieldElement5.Multiply(b));
					eCFieldElement4 = eCFieldElement5.Add(beta);
				}
				if (!eCFieldElement4.IsZero)
				{
					return null;
				}
				eCFieldElement6 = eCFieldElement3.Square().Add(eCFieldElement3);
			}
			while (eCFieldElement6.IsZero);
			return eCFieldElement3;
		}

		internal virtual BigInteger[] GetSi()
		{
			if (si == null)
			{
				lock (this)
				{
					if (si == null)
					{
						si = Tnaf.GetSi(this);
					}
				}
			}
			return si;
		}
	}
}
namespace Org.BouncyCastle.Math.EC.Custom.Sec
{
	internal class SecT113R1Curve : AbstractF2mCurve
	{
		private class SecT113R1LookupTable : AbstractECLookupTable
		{
			private readonly SecT113R1Curve m_outer;

			private readonly ulong[] m_table;

			private readonly int m_size;

			public override int Size => m_size;

			internal SecT113R1LookupTable(SecT113R1Curve outer, ulong[] table, int size)
			{
				m_outer = outer;
				m_table = table;
				m_size = size;
			}

			public override ECPoint Lookup(int index)
			{
				ulong[] array = Nat128.Create64();
				ulong[] array2 = Nat128.Create64();
				int num = 0;
				for (int i = 0; i < m_size; i++)
				{
					ulong num2 = (ulong)((i ^ index) - 1 >> 31);
					for (int j = 0; j < 2; j++)
					{
						ulong[] array3;
						ulong[] array4 = (array3 = array);
						int num3 = j;
						nint num4 = num3;
						array4[num3] = array3[num4] ^ (m_table[num + j] & num2);
						ulong[] array5 = (array3 = array2);
						int num5 = j;
						num4 = num5;
						array5[num5] = array3[num4] ^ (m_table[num + 2 + j] & num2);
					}
					num += 4;
				}
				return CreatePoint(array, array2);
			}

			public override ECPoint LookupVar(int index)
			{
				ulong[] array = Nat128.Create64();
				ulong[] array2 = Nat128.Create64();
				int num = index * 2 * 2;
				for (int i = 0; i < 2; i++)
				{
					array[i] = m_table[num + i];
					array2[i] = m_table[num + 2 + i];
				}
				return CreatePoint(array, array2);
			}

			private ECPoint CreatePoint(ulong[] x, ulong[] y)
			{
				return m_outer.CreateRawPoint(new SecT113FieldElement(x), new SecT113FieldElement(y), SECT113R1_AFFINE_ZS, withCompression: false);
			}
		}

		private const int SECT113R1_DEFAULT_COORDS = 6;

		private const int SECT113R1_FE_LONGS = 2;

		private static readonly ECFieldElement[] SECT113R1_AFFINE_ZS = new ECFieldElement[1]
		{
			new SecT113FieldElement(BigInteger.One)
		};

		protected readonly SecT113R1Point m_infinity;

		public override ECPoint Infinity => m_infinity;

		public override int FieldSize => 113;

		public override bool IsKoblitz => false;

		public virtual int M => 113;

		public virtual bool IsTrinomial => true;

		public virtual int K1 => 9;

		public virtual int K2 => 0;

		public virtual int K3 => 0;

		public SecT113R1Curve()
			: base(113, 9, 0, 0)
		{
			m_infinity = new SecT113R1Point(this, null, null);
			m_a = FromBigInteger(new BigInteger(1, Hex.DecodeStrict("003088250CA6E7C7FE649CE85820F7")));
			m_b = FromBigInteger(new BigInteger(1, Hex.DecodeStrict("00E8BEE4D3E2260744188BE0E9C723")));
			m_order = new BigInteger(1, Hex.DecodeStrict("0100000000000000D9CCEC8A39E56F"));
			m_cofactor = BigInteger.Two;
			m_coord = 6;
		}

		protected override ECCurve CloneCurve()
		{
			return new SecT113R1Curve();
		}

		public override bool SupportsCoordinateSystem(int coord)
		{
			if (coord == 6)
			{
				return true;
			}
			return false;
		}

		public override ECFieldElement FromBigInteger(BigInteger x)
		{
			return new SecT113FieldElement(x);
		}

		protected internal override ECPoint CreateRawPoint(ECFieldElement x, ECFieldElement y, bool withCompression)
		{
			return new SecT113R1Point(this, x, y, withCompression);
		}

		protected internal override ECPoint CreateRawPoint(ECFieldElement x, ECFieldElement y, ECFieldElement[] zs, bool withCompression)
		{
			return new SecT113R1Point(this, x, y, zs, withCompression);
		}

		public override ECLookupTable CreateCacheSafeLookupTable(ECPoint[] points, int off, int len)
		{
			ulong[] array = new ulong[len * 2 * 2];
			int num = 0;
			for (int i = 0; i < len; i++)
			{
				ECPoint eCPoint = points[off + i];
				Nat128.Copy64(((SecT113FieldElement)eCPoint.RawXCoord).x, 0, array, num);
				num += 2;
				Nat128.Copy64(((SecT113FieldElement)eCPoint.RawYCoord).x, 0, array, num);
				num += 2;
			}
			return new SecT113R1LookupTable(this, array, len);
		}
	}
}
namespace Org.BouncyCastle.Math.EC
{
	public abstract class AbstractF2mPoint : ECPointBase
	{
		protected AbstractF2mPoint(ECCurve curve, ECFieldElement x, ECFieldElement y, bool withCompression)
			: base(curve, x, y, withCompression)
		{
		}

		protected AbstractF2mPoint(ECCurve curve, ECFieldElement x, ECFieldElement y, ECFieldElement[] zs, bool withCompression)
			: base(curve, x, y, zs, withCompression)
		{
		}

		protected override bool SatisfiesCurveEquation()
		{
			ECCurve curve = Curve;
			ECFieldElement rawXCoord = base.RawXCoord;
			ECFieldElement rawYCoord = base.RawYCoord;
			ECFieldElement eCFieldElement = curve.A;
			ECFieldElement eCFieldElement2 = curve.B;
			int coordinateSystem = curve.CoordinateSystem;
