	public interface ECMultiplier
	{
		ECPoint Multiply(ECPoint p, BigInteger k);
	}
	public abstract class AbstractECMultiplier : ECMultiplier
	{
		public virtual ECPoint Multiply(ECPoint p, BigInteger k)
		{
			int signValue = k.SignValue;
			if (signValue == 0 || p.IsInfinity)
			{
				return p.Curve.Infinity;
			}
			ECPoint eCPoint = MultiplyPositive(p, k.Abs());
			ECPoint p2 = ((signValue > 0) ? eCPoint : eCPoint.Negate());
			return CheckResult(p2);
		}

		protected abstract ECPoint MultiplyPositive(ECPoint p, BigInteger k);

		protected virtual ECPoint CheckResult(ECPoint p)
		{
			return ECAlgorithms.ImplCheckResult(p);
		}
	}
	[Obsolete("Will be removed")]
	public class DoubleAddMultiplier : AbstractECMultiplier
	{
		protected override ECPoint MultiplyPositive(ECPoint p, BigInteger k)
		{
			ECPoint[] array = new ECPoint[2]
			{
				p.Curve.Infinity,
				p
			};
			int bitLength = k.BitLength;
			for (int i = 0; i < bitLength; i++)
			{
				int num = (k.TestBit(i) ? 1 : 0);
				int num2 = 1 - num;
				array[num2] = array[num2].TwicePlus(array[num]);
			}
			return array[0];
		}
	}
	public class FixedPointCombMultiplier : AbstractECMultiplier
	{
		protected override ECPoint MultiplyPositive(ECPoint p, BigInteger k)
		{
			ECCurve curve = p.Curve;
			int combSize = FixedPointUtilities.GetCombSize(curve);
			if (k.BitLength > combSize)
			{
				throw new InvalidOperationException("fixed-point comb doesn't support scalars larger than the curve order");
			}
			FixedPointPreCompInfo fixedPointPreCompInfo = FixedPointUtilities.Precompute(p);
			ECLookupTable lookupTable = fixedPointPreCompInfo.LookupTable;
			int width = fixedPointPreCompInfo.Width;
			int num = (combSize + width - 1) / width;
			ECPoint eCPoint = curve.Infinity;
			int num2 = num * width;
			uint[] array = Nat.FromBigInteger(num2, k);
			int num3 = num2 - 1;
			for (int i = 0; i < num; i++)
			{
				uint num4 = 0u;
				for (int num5 = num3 - i; num5 >= 0; num5 -= num)
				{
					uint num6 = array[num5 >> 5] >> num5;
					num4 ^= num6 >> 1;
					num4 <<= 1;
					num4 ^= num6;
				}
				ECPoint b = lookupTable.Lookup((int)num4);
				eCPoint = eCPoint.TwicePlus(b);
			}
			return eCPoint.Add(fixedPointPreCompInfo.Offset);
		}
	}
