	public class FixedPointUtilities
	{
		private class FixedPointCallback : IPreCompCallback
		{
			private readonly ECPoint m_p;

			internal FixedPointCallback(ECPoint p)
			{
				m_p = p;
			}

			public PreCompInfo Precompute(PreCompInfo existing)
			{
				FixedPointPreCompInfo fixedPointPreCompInfo = ((existing is FixedPointPreCompInfo) ? ((FixedPointPreCompInfo)existing) : null);
				ECCurve curve = m_p.Curve;
				int combSize = GetCombSize(curve);
				int num = ((combSize > 250) ? 6 : 5);
				int num2 = 1 << num;
				if (CheckExisting(fixedPointPreCompInfo, num2))
				{
					return fixedPointPreCompInfo;
				}
				int e = (combSize + num - 1) / num;
				ECPoint[] array = new ECPoint[num + 1];
				array[0] = m_p;
				for (int i = 1; i < num; i++)
				{
					array[i] = array[i - 1].TimesPow2(e);
				}
				array[num] = array[0].Subtract(array[1]);
				curve.NormalizeAll(array);
				ECPoint[] array2 = new ECPoint[num2];
				array2[0] = array[0];
				for (int num3 = num - 1; num3 >= 0; num3--)
				{
					ECPoint b = array[num3];
					int num4 = 1 << num3;
					for (int j = num4; j < num2; j += num4 << 1)
					{
						array2[j] = array2[j - num4].Add(b);
					}
				}
				curve.NormalizeAll(array2);
				FixedPointPreCompInfo fixedPointPreCompInfo2 = new FixedPointPreCompInfo();
				fixedPointPreCompInfo2.LookupTable = curve.CreateCacheSafeLookupTable(array2, 0, array2.Length);
				fixedPointPreCompInfo2.Offset = array[num];
				fixedPointPreCompInfo2.Width = num;
				return fixedPointPreCompInfo2;
			}

			private bool CheckExisting(FixedPointPreCompInfo existingFP, int n)
			{
				if (existingFP != null)
				{
					return CheckTable(existingFP.LookupTable, n);
				}
				return false;
			}

			private bool CheckTable(ECLookupTable table, int n)
			{
				if (table != null)
				{
					return table.Size >= n;
				}
				return false;
			}
		}

		public static readonly string PRECOMP_NAME = "bc_fixed_point";

		public static int GetCombSize(ECCurve c)
		{
			return c.Order?.BitLength ?? (c.FieldSize + 1);
		}

		public static FixedPointPreCompInfo GetFixedPointPreCompInfo(PreCompInfo preCompInfo)
		{
			return preCompInfo as FixedPointPreCompInfo;
		}

		public static FixedPointPreCompInfo Precompute(ECPoint p)
		{
			return (FixedPointPreCompInfo)p.Curve.Precompute(p, PRECOMP_NAME, new FixedPointCallback(p));
		}
	}
	public class GlvMultiplier : AbstractECMultiplier
	{
		protected readonly ECCurve curve;

		protected readonly GlvEndomorphism glvEndomorphism;

		public GlvMultiplier(ECCurve curve, GlvEndomorphism glvEndomorphism)
		{
			if (curve == null || curve.Order == null)
			{
				throw new ArgumentException("Need curve with known group order", "curve");
			}
			this.curve = curve;
			this.glvEndomorphism = glvEndomorphism;
		}

		protected override ECPoint MultiplyPositive(ECPoint p, BigInteger k)
		{
			if (!curve.Equals(p.Curve))
			{
				throw new InvalidOperationException();
			}
			BigInteger order = p.Curve.Order;
			BigInteger[] array = glvEndomorphism.DecomposeScalar(k.Mod(order));
			BigInteger k2 = array[0];
			BigInteger l = array[1];
			if (glvEndomorphism.HasEfficientPointMap)
			{
				return ECAlgorithms.ImplShamirsTrickWNaf(glvEndomorphism, p, k2, l);
			}
			ECPoint q = EndoUtilities.MapPoint(glvEndomorphism, p);
			return ECAlgorithms.ImplShamirsTrickWNaf(p, k2, q, l);
		}
	}
	[Obsolete("Will be removed")]
	public class MixedNafR2LMultiplier : AbstractECMultiplier
	{
		protected readonly int additionCoord;

		protected readonly int doublingCoord;

		public MixedNafR2LMultiplier()
			: this(2, 4)
		{
		}

		public MixedNafR2LMultiplier(int additionCoord, int doublingCoord)
		{
			this.additionCoord = additionCoord;
			this.doublingCoord = doublingCoord;
		}

		protected override ECPoint MultiplyPositive(ECPoint p, BigInteger k)
		{
			ECCurve curve = p.Curve;
			ECCurve eCCurve = ConfigureCurve(curve, additionCoord);
			ECCurve eCCurve2 = ConfigureCurve(curve, doublingCoord);
			int[] array = WNafUtilities.GenerateCompactNaf(k);
			ECPoint eCPoint = eCCurve.Infinity;
			ECPoint eCPoint2 = eCCurve2.ImportPoint(p);
			int num = 0;
			foreach (int num2 in array)
			{
				int num3 = num2 >> 16;
				num += num2 & 0xFFFF;
				eCPoint2 = eCPoint2.TimesPow2(num);
				ECPoint eCPoint3 = eCCurve.ImportPoint(eCPoint2);
				if (num3 < 0)
				{
					eCPoint3 = eCPoint3.Negate();
				}
				eCPoint = eCPoint.Add(eCPoint3);
				num = 1;
			}
			return curve.ImportPoint(eCPoint);
		}

		protected virtual ECCurve ConfigureCurve(ECCurve c, int coord)
		{
			if (c.CoordinateSystem == coord)
			{
				return c;
			}
			if (!c.SupportsCoordinateSystem(coord))
			{
				throw new ArgumentException("Coordinate system " + coord + " not supported by this curve", "coord");
			}
			return c.Configure().SetCoordinateSystem(coord).Create();
		}
	}
	[Obsolete("Will be removed")]
	public class MontgomeryLadderMultiplier : AbstractECMultiplier
	{
		protected override ECPoint MultiplyPositive(ECPoint p, BigInteger k)
		{
			ECPoint[] array = new ECPoint[2]
			{
				p.Curve.Infinity,
				p
			};
			int bitLength = k.BitLength;
			int num = bitLength;
			while (--num >= 0)
			{
				int num2 = (k.TestBit(num) ? 1 : 0);
				int num3 = 1 - num2;
				array[num3] = array[num3].Add(array[num2]);
				array[num2] = array[num2].Twice();
			}
			return array[0];
		}
	}
	[Obsolete("Will be removed")]
	public class NafL2RMultiplier : AbstractECMultiplier
	{
		protected override ECPoint MultiplyPositive(ECPoint p, BigInteger k)
		{
			int[] array = WNafUtilities.GenerateCompactNaf(k);
			ECPoint eCPoint = p.Normalize();
			ECPoint eCPoint2 = eCPoint.Negate();
			ECPoint eCPoint3 = p.Curve.Infinity;
			int num = array.Length;
			while (--num >= 0)
			{
				int num2 = array[num];
				int num3 = num2 >> 16;
				int e = num2 & 0xFFFF;
				eCPoint3 = eCPoint3.TwicePlus((num3 < 0) ? eCPoint2 : eCPoint);
				eCPoint3 = eCPoint3.TimesPow2(e);
			}
			return eCPoint3;
		}
	}
	[Obsolete("Will be removed")]
	public class NafR2LMultiplier : AbstractECMultiplier
	{
		protected override ECPoint MultiplyPositive(ECPoint p, BigInteger k)
		{
			int[] array = WNafUtilities.GenerateCompactNaf(k);
			ECPoint eCPoint = p.Curve.Infinity;
			ECPoint eCPoint2 = p;
			int num = 0;
			foreach (int num2 in array)
			{
				int num3 = num2 >> 16;
				num += num2 & 0xFFFF;
				eCPoint2 = eCPoint2.TimesPow2(num);
				eCPoint = eCPoint.Add((num3 < 0) ? eCPoint2.Negate() : eCPoint2);
				num = 1;
			}
			return eCPoint;
		}
	}
