					if (num5 != 0)
					{
						int num7 = System.Math.Abs(num5);
						ECPoint[] array2 = ((num5 < 0) ? preCompNegQ : preCompQ);
						eCPoint2 = eCPoint2.Add(array2[num7 >> 1]);
