		private byte[] ToByteArray(bool unsigned)
		{
			if (sign == 0)
			{
				if (!unsigned)
				{
					return new byte[1];
				}
				return ZeroEncoding;
			}
			int num = ((unsigned && sign > 0) ? BitLength : (BitLength + 1));
			int byteLength = GetByteLength(num);
			byte[] array = new byte[byteLength];
			int num2 = magnitude.Length;
			int num3 = array.Length;
			if (sign > 0)
			{
				while (num2 > 1)
				{
					uint num4 = (uint)magnitude[--num2];
					array[--num3] = (byte)num4;
					array[--num3] = (byte)(num4 >> 8);
					array[--num3] = (byte)(num4 >> 16);
					array[--num3] = (byte)(num4 >> 24);
				}
				uint num5;
				for (num5 = (uint)magnitude[0]; num5 > 255; num5 >>= 8)
				{
					array[--num3] = (byte)num5;
				}
				array[--num3] = (byte)num5;
			}
			else
			{
				bool flag = true;
				while (num2 > 1)
				{
					uint num6 = (uint)(~magnitude[--num2]);
					if (flag)
					{
						flag = ++num6 == 0;
					}
					array[--num3] = (byte)num6;
					array[--num3] = (byte)(num6 >> 8);
					array[--num3] = (byte)(num6 >> 16);
					array[--num3] = (byte)(num6 >> 24);
				}
				uint num7 = (uint)magnitude[0];
				if (flag)
				{
					num7--;
				}
				while (num7 > 255)
				{
					array[--num3] = (byte)(~num7);
					num7 >>= 8;
				}
				array[--num3] = (byte)(~num7);
				if (num3 > 0)
				{
					array[--num3] = byte.MaxValue;
				}
			}
			return array;
		}

		public override string ToString()
		{
			return ToString(10);
		}

		public string ToString(int radix)
		{
			switch (radix)
			{
			default:
				throw new FormatException("Only bases 2, 8, 10, 16 are allowed");
			case 2:
			case 8:
			case 10:
			case 16:
			{
				if (magnitude == null)
				{
					return "null";
				}
				if (sign == 0)
				{
					return "0";
				}
				int i;
				for (i = 0; i < magnitude.Length && magnitude[i] == 0; i++)
				{
				}
				if (i == magnitude.Length)
				{
					return "0";
				}
				StringBuilder stringBuilder = new StringBuilder();
				if (sign == -1)
				{
					stringBuilder.Append('-');
				}
				switch (radix)
				{
				case 2:
				{
					int num5 = i;
					stringBuilder.Append(Convert.ToString(magnitude[num5], 2));
					while (++num5 < magnitude.Length)
					{
						AppendZeroExtendedString(stringBuilder, Convert.ToString(magnitude[num5], 2), 32);
					}
					break;
				}
				case 8:
				{
					int num = 1073741823;
					BigInteger bigInteger3 = Abs();
					int num2 = bigInteger3.BitLength;
					IList list2 = Platform.CreateArrayList();
					while (num2 > 30)
					{
						list2.Add(Convert.ToString(bigInteger3.IntValue & num, 8));
						bigInteger3 = bigInteger3.ShiftRight(30);
						num2 -= 30;
					}
					stringBuilder.Append(Convert.ToString(bigInteger3.IntValue, 8));
					for (int num3 = list2.Count - 1; num3 >= 0; num3--)
					{
						AppendZeroExtendedString(stringBuilder, (string)list2[num3], 10);
					}
					break;
				}
				case 16:
				{
					int num4 = i;
					stringBuilder.Append(Convert.ToString(magnitude[num4], 16));
					while (++num4 < magnitude.Length)
					{
						AppendZeroExtendedString(stringBuilder, Convert.ToString(magnitude[num4], 16), 8);
					}
					break;
				}
				case 10:
				{
					BigInteger bigInteger = Abs();
					if (bigInteger.BitLength < 64)
					{
						stringBuilder.Append(Convert.ToString(bigInteger.LongValue, radix));
						break;
					}
					IList list = Platform.CreateArrayList();
					BigInteger bigInteger2 = ValueOf(radix);
					while (bigInteger2.CompareTo(bigInteger) <= 0)
					{
						list.Add(bigInteger2);
						bigInteger2 = bigInteger2.Square();
					}
					int count = list.Count;
					stringBuilder.EnsureCapacity(stringBuilder.Length + (1 << count));
					ToString(stringBuilder, radix, list, count, bigInteger);
					break;
				}
				}
				return stringBuilder.ToString();
			}
			}
		}

		private static void ToString(StringBuilder sb, int radix, IList moduli, int scale, BigInteger pos)
		{
			if (pos.BitLength < 64)
			{
				string text = Convert.ToString(pos.LongValue, radix);
				if (sb.Length > 1 || (sb.Length == 1 && sb[0] != '-'))
				{
					AppendZeroExtendedString(sb, text, 1 << scale);
				}
				else if (pos.SignValue != 0)
				{
					sb.Append(text);
				}
			}
			else
			{
				BigInteger[] array = pos.DivideAndRemainder((BigInteger)moduli[--scale]);
				ToString(sb, radix, moduli, scale, array[0]);
				ToString(sb, radix, moduli, scale, array[1]);
			}
		}

		private static void AppendZeroExtendedString(StringBuilder sb, string s, int minLength)
		{
			for (int i = s.Length; i < minLength; i++)
			{
				sb.Append('0');
			}
			sb.Append(s);
		}

		private static BigInteger CreateUValueOf(ulong value)
		{
			int num = (int)(value >> 32);
			int num2 = (int)value;
			if (num != 0)
			{
				return new BigInteger(1, new int[2] { num, num2 }, checkMag: false);
			}
			if (num2 != 0)
			{
				BigInteger bigInteger = new BigInteger(1, new int[1] { num2 }, checkMag: false);
				if ((num2 & -num2) == num2)
				{
					bigInteger.nBits = 1;
				}
				return bigInteger;
			}
			return Zero;
		}

		private static BigInteger CreateValueOf(long value)
		{
			if (value < 0)
			{
				if (value == long.MinValue)
				{
					return CreateValueOf(~value).Not();
				}
				return CreateValueOf(-value).Negate();
			}
			return CreateUValueOf((ulong)value);
		}

		public static BigInteger ValueOf(long value)
		{
			if (value >= 0 && value < SMALL_CONSTANTS.Length)
			{
				return SMALL_CONSTANTS[value];
			}
			return CreateValueOf(value);
		}

		public int GetLowestSetBit()
		{
			if (sign == 0)
			{
				return -1;
			}
			return GetLowestSetBitMaskFirst(-1);
		}

		private int GetLowestSetBitMaskFirst(int firstWordMask)
		{
			int num = magnitude.Length;
			int num2 = 0;
			uint num3 = (uint)(magnitude[--num] & firstWordMask);
			while (num3 == 0)
			{
				num3 = (uint)magnitude[--num];
				num2 += 32;
			}
			while ((num3 & 0xFF) == 0)
			{
				num3 >>= 8;
				num2 += 8;
			}
			while ((num3 & 1) == 0)
			{
				num3 >>= 1;
				num2++;
			}
			return num2;
		}

		public bool TestBit(int n)
		{
			if (n < 0)
			{
				throw new ArithmeticException("Bit position must not be negative");
			}
			if (sign < 0)
			{
				return !Not().TestBit(n);
			}
			int num = n / 32;
			if (num >= magnitude.Length)
			{
				return false;
			}
			int num2 = magnitude[magnitude.Length - 1 - num];
			return ((num2 >> n % 32) & 1) > 0;
		}

		public BigInteger Or(BigInteger value)
		{
			if (sign == 0)
			{
				return value;
			}
			if (value.sign == 0)
			{
				return this;
			}
			int[] array = ((sign > 0) ? magnitude : Add(One).magnitude);
			int[] array2 = ((value.sign > 0) ? value.magnitude : value.Add(One).magnitude);
			bool flag = sign < 0 || value.sign < 0;
			int num = System.Math.Max(array.Length, array2.Length);
			int[] array3 = new int[num];
			int num2 = array3.Length - array.Length;
			int num3 = array3.Length - array2.Length;
			for (int i = 0; i < array3.Length; i++)
			{
				int num4 = ((i >= num2) ? array[i - num2] : 0);
				int num5 = ((i >= num3) ? array2[i - num3] : 0);
				if (sign < 0)
				{
					num4 = ~num4;
				}
				if (value.sign < 0)
				{
					num5 = ~num5;
				}
				array3[i] = num4 | num5;
				if (flag)
				{
					array3[i] = ~array3[i];
				}
			}
			BigInteger bigInteger = new BigInteger(1, array3, checkMag: true);
			if (flag)
			{
				bigInteger = bigInteger.Not();
			}
			return bigInteger;
		}

		public BigInteger Xor(BigInteger value)
		{
			if (sign == 0)
			{
				return value;
			}
			if (value.sign == 0)
			{
				return this;
			}
			int[] array = ((sign > 0) ? magnitude : Add(One).magnitude);
			int[] array2 = ((value.sign > 0) ? value.magnitude : value.Add(One).magnitude);
			bool flag = (sign < 0 && value.sign >= 0) || (sign >= 0 && value.sign < 0);
			int num = System.Math.Max(array.Length, array2.Length);
			int[] array3 = new int[num];
			int num2 = array3.Length - array.Length;
			int num3 = array3.Length - array2.Length;
			for (int i = 0; i < array3.Length; i++)
			{
				int num4 = ((i >= num2) ? array[i - num2] : 0);
				int num5 = ((i >= num3) ? array2[i - num3] : 0);
				if (sign < 0)
				{
					num4 = ~num4;
				}
				if (value.sign < 0)
				{
					num5 = ~num5;
				}
				array3[i] = num4 ^ num5;
				if (flag)
				{
					array3[i] = ~array3[i];
				}
			}
			BigInteger bigInteger = new BigInteger(1, array3, checkMag: true);
			if (flag)
			{
				bigInteger = bigInteger.Not();
			}
			return bigInteger;
		}

		public BigInteger SetBit(int n)
		{
			if (n < 0)
			{
				throw new ArithmeticException("Bit address less than zero");
			}
			if (TestBit(n))
			{
				return this;
			}
			if (sign > 0 && n < BitLength - 1)
			{
				return FlipExistingBit(n);
			}
			return Or(One.ShiftLeft(n));
		}

		public BigInteger ClearBit(int n)
		{
			if (n < 0)
			{
				throw new ArithmeticException("Bit address less than zero");
			}
			if (!TestBit(n))
			{
				return this;
			}
			if (sign > 0 && n < BitLength - 1)
			{
				return FlipExistingBit(n);
			}
			return AndNot(One.ShiftLeft(n));
		}

		public BigInteger FlipBit(int n)
		{
			if (n < 0)
			{
				throw new ArithmeticException("Bit address less than zero");
			}
			if (sign > 0 && n < BitLength - 1)
			{
				return FlipExistingBit(n);
			}
			return Xor(One.ShiftLeft(n));
		}

		private BigInteger FlipExistingBit(int n)
		{
			int[] array = (int[])magnitude.Clone();
			int[] array2;
			int[] array3 = (array2 = array);
			int num = array.Length - 1 - (n >> 5);
			nint num2 = num;
			array3[num] = array2[num2] ^ (1 << (n & 0x1F));
			return new BigInteger(sign, array, checkMag: false);
		}
	}
	public abstract class Primes
	{
		public class MROutput
		{
			private readonly bool mProvablyComposite;

			private readonly BigInteger mFactor;

			public BigInteger Factor => mFactor;

			public bool IsProvablyComposite => mProvablyComposite;

			public bool IsNotPrimePower
			{
				get
				{
					if (mProvablyComposite)
					{
						return mFactor == null;
					}
					return false;
				}
			}

			internal static MROutput ProbablyPrime()
			{
				return new MROutput(provablyComposite: false, null);
			}

			internal static MROutput ProvablyCompositeWithFactor(BigInteger factor)
			{
				return new MROutput(provablyComposite: true, factor);
			}

			internal static MROutput ProvablyCompositeNotPrimePower()
			{
				return new MROutput(provablyComposite: true, null);
			}

			private MROutput(bool provablyComposite, BigInteger factor)
			{
				mProvablyComposite = provablyComposite;
				mFactor = factor;
			}
		}

		public class STOutput
		{
			private readonly BigInteger mPrime;

			private readonly byte[] mPrimeSeed;

			private readonly int mPrimeGenCounter;

			public BigInteger Prime => mPrime;

			public byte[] PrimeSeed => mPrimeSeed;

			public int PrimeGenCounter => mPrimeGenCounter;

			internal STOutput(BigInteger prime, byte[] primeSeed, int primeGenCounter)
			{
				mPrime = prime;
				mPrimeSeed = primeSeed;
				mPrimeGenCounter = primeGenCounter;
			}
		}

		public static readonly int SmallFactorLimit = 211;

		private static readonly BigInteger One = BigInteger.One;

		private static readonly BigInteger Two = BigInteger.Two;

		private static readonly BigInteger Three = BigInteger.Three;

		public static STOutput GenerateSTRandomPrime(IDigest hash, int length, byte[] inputSeed)
		{
			if (hash == null)
			{
				throw new ArgumentNullException("hash");
			}
			if (length < 2)
			{
				throw new ArgumentException("must be >= 2", "length");
			}
			if (inputSeed == null)
			{
				throw new ArgumentNullException("inputSeed");
			}
			if (inputSeed.Length == 0)
			{
				throw new ArgumentException("cannot be empty", "inputSeed");
			}
			return ImplSTRandomPrime(hash, length, Arrays.Clone(inputSeed));
		}

		public static MROutput EnhancedMRProbablePrimeTest(BigInteger candidate, SecureRandom random, int iterations)
		{
			CheckCandidate(candidate, "candidate");
			if (random == null)
			{
				throw new ArgumentNullException("random");
			}
			if (iterations < 1)
			{
				throw new ArgumentException("must be > 0", "iterations");
			}
			if (candidate.BitLength == 2)
			{
				return MROutput.ProbablyPrime();
			}
			if (!candidate.TestBit(0))
			{
				return MROutput.ProvablyCompositeWithFactor(Two);
			}
			BigInteger bigInteger = candidate.Subtract(One);
			BigInteger max = candidate.Subtract(Two);
			int lowestSetBit = bigInteger.GetLowestSetBit();
			BigInteger e = bigInteger.ShiftRight(lowestSetBit);
			for (int i = 0; i < iterations; i++)
			{
				BigInteger bigInteger2 = BigIntegers.CreateRandomInRange(Two, max, random);
				BigInteger bigInteger3 = bigInteger2.Gcd(candidate);
				if (bigInteger3.CompareTo(One) > 0)
				{
					return MROutput.ProvablyCompositeWithFactor(bigInteger3);
				}
				BigInteger bigInteger4 = bigInteger2.ModPow(e, candidate);
				if (bigInteger4.Equals(One) || bigInteger4.Equals(bigInteger))
				{
					continue;
				}
				bool flag = false;
				BigInteger bigInteger5 = bigInteger4;
				for (int j = 1; j < lowestSetBit; j++)
				{
					bigInteger4 = bigInteger4.ModPow(Two, candidate);
					if (bigInteger4.Equals(bigInteger))
					{
						flag = true;
						break;
					}
					if (bigInteger4.Equals(One))
					{
						break;
					}
					bigInteger5 = bigInteger4;
				}
				if (flag)
				{
					continue;
				}
				if (!bigInteger4.Equals(One))
				{
					bigInteger5 = bigInteger4;
					bigInteger4 = bigInteger4.ModPow(Two, candidate);
					if (!bigInteger4.Equals(One))
					{
						bigInteger5 = bigInteger4;
					}
				}
				bigInteger3 = bigInteger5.Subtract(One).Gcd(candidate);
				if (bigInteger3.CompareTo(One) > 0)
				{
					return MROutput.ProvablyCompositeWithFactor(bigInteger3);
				}
				return MROutput.ProvablyCompositeNotPrimePower();
			}
			return MROutput.ProbablyPrime();
		}

		public static bool HasAnySmallFactors(BigInteger candidate)
		{
			CheckCandidate(candidate, "candidate");
			return ImplHasAnySmallFactors(candidate);
		}

		public static bool IsMRProbablePrime(BigInteger candidate, SecureRandom random, int iterations)
		{
			CheckCandidate(candidate, "candidate");
			if (random == null)
			{
				throw new ArgumentException("cannot be null", "random");
			}
			if (iterations < 1)
			{
				throw new ArgumentException("must be > 0", "iterations");
			}
			if (candidate.BitLength == 2)
			{
				return true;
			}
			if (!candidate.TestBit(0))
			{
				return false;
			}
			BigInteger bigInteger = candidate.Subtract(One);
			BigInteger max = candidate.Subtract(Two);
			int lowestSetBit = bigInteger.GetLowestSetBit();
			BigInteger m = bigInteger.ShiftRight(lowestSetBit);
			for (int i = 0; i < iterations; i++)
			{
				BigInteger b = BigIntegers.CreateRandomInRange(Two, max, random);
				if (!ImplMRProbablePrimeToBase(candidate, bigInteger, m, lowestSetBit, b))
				{
					return false;
				}
			}
			return true;
		}

		public static bool IsMRProbablePrimeToBase(BigInteger candidate, BigInteger baseValue)
		{
			CheckCandidate(candidate, "candidate");
			CheckCandidate(baseValue, "baseValue");
			if (baseValue.CompareTo(candidate.Subtract(One)) >= 0)
			{
				throw new ArgumentException("must be < ('candidate' - 1)", "baseValue");
			}
			if (candidate.BitLength == 2)
			{
				return true;
			}
			BigInteger bigInteger = candidate.Subtract(One);
			int lowestSetBit = bigInteger.GetLowestSetBit();
			BigInteger m = bigInteger.ShiftRight(lowestSetBit);
			return ImplMRProbablePrimeToBase(candidate, bigInteger, m, lowestSetBit, baseValue);
		}

		private static void CheckCandidate(BigInteger n, string name)
		{
			if (n == null || n.SignValue < 1 || n.BitLength < 2)
			{
				throw new ArgumentException("must be non-null and >= 2", name);
			}
		}

