		}

		public override bool Equals(object obj)
		{
			if (!(obj is AsymmetricKeyEntry asymmetricKeyEntry))
			{
				return false;
			}
			return key.Equals(asymmetricKeyEntry.key);
		}

		public override int GetHashCode()
		{
