				parameters = pbeParametersGenerator.GenerateDerivedParameters(algorithm2.Id, keySize);
				if (array2 != null && !Arrays.AreEqual(array2, new byte[array2.Length]))
				{
					parameters = new ParametersWithIV(parameters, array2);
				}
