		public static int Decode(string data, Stream outStr)
		{
			return encoder.DecodeString(data, outStr);
		}
	}
	public class UrlBase64Encoder : Base64Encoder
	{
		public UrlBase64Encoder()
		{
			encodingTable[encodingTable.Length - 2] = 45;
