			: this(type, Platform.CreateArrayList(), content)
		{
		}

		public PemObject(string type, IList headers, byte[] content)
		{
			this.type = type;
			this.headers = Platform.CreateArrayList(headers);
			this.content = content;
		}

		public PemObject Generate()
		{
			return this;
		}
	}
