			int num2 = bToIndex - bFromIndex;
			if (num != num2)
			{
				return false;
			}
			for (int i = 0; i < num; i++)
			{
				if (a[aFromIndex + i] != b[bFromIndex + i])
				{
					return false;
				}
			}
			return true;
		}

