		public static byte[] ConcatenateAll(params byte[][] vs)
		{
			byte[][] array = new byte[vs.Length][];
			int num = 0;
			int num2 = 0;
			foreach (byte[] array2 in vs)
			{
				if (array2 != null)
				{
					array[num++] = array2;
					num2 += array2.Length;
				}
			}
			byte[] array3 = new byte[num2];
			int num3 = 0;
			for (int j = 0; j < num; j++)
			{
				byte[] array4 = array[j];
				Array.Copy(array4, 0, array3, num3, array4.Length);
				num3 += array4.Length;
			}
			return array3;
		}

