		public void AddCrlEntry(BigInteger userCertificate, DateTime revocationDate, int reason)
		{
			tbsGen.AddCrlEntry(new DerInteger(userCertificate), new Org.BouncyCastle.Asn1.X509.Time(revocationDate), reason);
		}

		public void AddCrlEntry(BigInteger userCertificate, DateTime revocationDate, int reason, DateTime invalidityDate)
		{
			tbsGen.AddCrlEntry(new DerInteger(userCertificate), new Org.BouncyCastle.Asn1.X509.Time(revocationDate), reason, new DerGeneralizedTime(invalidityDate));
		}

