			}
			catch (Exception innerException)
			{
				throw new ArgumentException("Unknown signature type requested", innerException);
			}
			sigAlgId = X509Utilities.GetSigAlgID(sigOID, signatureAlgorithm);
			tbsGen.SetSignature(sigAlgId);
		}

