				}
				if (c == '\uffff')
				{
					CompressedStreamEOF();
				}
				int num = c;
				bsBuff = (bsBuff << 8) | (num & 0xFF);
				bsLive += 8;
			}
			int result = (bsBuff >> bsLive - n) & ((1 << n) - 1);
			bsLive -= n;
			return result;
		}

